Tutor.registerIndex("soc-mid", [
{"id":"soc-m-1-01","kind":"unit","title":"세계화 시대의 지리","text":"위치와 환경으로 세계 여러 지역의 특성을 추론하고, 서로 연결된 세계와 지역의 관계를 탐구해요. 절대적 위치와 상대적 위치를 구분하고, 위치와 자연·인문환경으로 지역의 특성을 추론할 수 있어요. 항공망·인터넷·글로벌 생산과 유통의 예로 공간적 상호 작용과 네트워크를 설명할 수 있어요. 지역·국가·세계의 여러 스케일에서 지역들이 서로 연결되어 있음을 사례로…","keywords":["절대적 위치","상대적 위치","자연환경","인문환경","공간적 상호 작용","네트워크","허브 공항","다국적 기업","세계화","지역화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c0","kind":"concept","title":"절대적 위치와 상대적 위치","text":"어떤 곳의 위치를 나타내는 방법은 크게 두 가지예요. 절대적 위치는 위도와 경도처럼 지구 어디에서나 똑같은 기준으로 나타낸 위치예요. 예를 들어 서울은 대략 북위 37°, 동경 127° 부근에 있어요. 위도와 경도는 주변이 어떻게 바뀌어도 달라지지 않아요. 상대적 위치는 주변의 대륙·바","keywords":["절대적 위치","상대적 위치"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c1","kind":"concept","title":"위치로 지역의 특성 추론하기","text":"위치를 알면 그 지역이 어떤 곳일지 짐작(추론)할 수 있어요. 위도 → 기온과 계절: 적도 부근(저위도)은 햇볕을 많이 받아 1년 내내 덥고, 극지방에 가까울수록(고위도) 추워요. 그 사이의 중위도는 사계절이 나타나요. 또 남반구는 북반구와 계절이 반대라서, 우리나라가 여름인 7월에 남","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c2","kind":"concept","title":"모자이크로서의 세계: 자연환경과 인문환경","text":"지역의 특성은 위치만이 아니라 그곳의 환경이 함께 만들어요. 자연환경: 사람이 만들지 않은 환경 — 지형(산·평야·하천), 기후, 식생(풀과 나무), 바다 등 인문환경: 사람이 만들어 온 환경 — 종교, 언어, 인구, 산업, 도시, 교통, 생활 양식 등 자연환경과 인문환경이 어우러져 지","keywords":["자연환경","인문환경"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c3","kind":"concept","title":"공간적 상호 작용과 네트워크","text":"공간적 상호 작용은 지역과 지역 사이에 사람·물건·정보·돈이 오가며 서로 영향을 주고받는 것이에요. 여행, 수출과 수입, 해외 송금, 인터넷 영상 시청이 모두 공간적 상호 작용이에요. 이렇게 지역들이 이어진 연결망을 네트워크라고 해요. 항공망: 비행기 노선의 연결망이에요. 많은 노선이 ","keywords":["공간적 상호 작용","네트워크","허브 공항","다국적 기업"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c4","kind":"concept","title":"다양한 스케일에서 서로 연결된 지역","text":"스케일은 지역을 바라보는 범위예요. 우리 동네·도시 같은 지역, 국가, 여러 나라를 묶은 큰 지역, 그리고 세계까지 여러 스케일이 있어요. 같은 일도 스케일을 바꾸어 보면 다른 모습이 보여요. 동네 빵집의 빵값이 올랐어요(지역). 까닭을 따라가 보면, 밀을 수입하는 나라(국가)가 있고,","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#c5","kind":"concept","title":"세계화와 지역화: 글로컬","text":"세계화는 교통·통신의 발달로 국경을 넘어 사람·물건·돈·문화가 활발하게 오가며 세계가 하나로 이어지는 현상이에요. 세계화가 지역에 주는 영향 다른 나라의 상품·음식·문화를 쉽게 접하고, 수출할 시장이 넓어져요. 값싼 외국 상품과 경쟁하게 되어 어려움을 겪는 지역 산업도 있어요. 세계 어","keywords":["세계화","지역화"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t0","kind":"term","title":"절대적 위치","text":"위도와 경도처럼 지구 어디에서나 똑같은 기준으로 나타낸 위치예요. 예: 북위 37°, 동경 127°","keywords":["절대적 위치"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t1","kind":"term","title":"상대적 위치","text":"주변의 대륙·바다·나라와의 관계로 나타낸 위치예요. 교통이나 주변 관계가 바뀌면 의미가 달라질 수 있어요. 예: 유라시아 대륙의 동쪽 끝","keywords":["상대적 위치"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t2","kind":"term","title":"자연환경","text":"지형·기후·식생·하천처럼 사람이 만들지 않은 환경이에요.","keywords":["자연환경"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t3","kind":"term","title":"인문환경","text":"종교·언어·인구·산업·교통처럼 사람이 만들어 온 환경이에요.","keywords":["인문환경"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t4","kind":"term","title":"공간적 상호 작용","text":"지역과 지역 사이에 사람·물건·정보·돈이 오가며 영향을 주고받는 것이에요.","keywords":["공간적 상호 작용"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t5","kind":"term","title":"네트워크","text":"지역들이 서로 이어진 연결망이에요. 예: 항공망, 해운망, 인터넷 망","keywords":["네트워크"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t6","kind":"term","title":"허브 공항","text":"많은 항공 노선이 모여 다른 곳으로 갈아타는 중심이 되는 공항이에요.","keywords":["허브 공항"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t7","kind":"term","title":"다국적 기업","text":"여러 나라에 본사·연구소·공장·판매 지점을 두고 활동하는 기업이에요.","keywords":["다국적 기업"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t8","kind":"term","title":"세계화","text":"국경을 넘어 사람·물건·돈·문화가 활발하게 오가며 세계가 하나로 이어지는 현상이에요.","keywords":["세계화"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#t9","kind":"term","title":"지역화","text":"지역의 고유한 특성이 세계적으로 가치를 갖게 되는 것이에요. 예: 지역 브랜드, 지리적 표시제, 지역 축제","keywords":["지역화"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#f0","kind":"faq","title":"절대적 위치랑 상대적 위치 중에 뭐가 더 중요해요?","text":"둘 다 중요하고, 쓰임이 달라요. 절대적 위치(위도·경도)는 어떤 곳을 정확하게 찾거나 기후·시각을 추론할 때 좋아요. 상대적 위치는 그 지역이 이웃과 어떤 관계인지, 교류하기 좋은 곳인지 이해할 때 좋아요. 지역을 제대로 알려면 둘을 함께 봐요.","keywords":["절대적 위치","상대적 위치"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#f1","kind":"faq","title":"세계화가 되면 모든 나라의 문화가 똑같아지나요?","text":"비슷한 상품과 문화가 퍼지면서 지역 고유의 문화가 약해질까 걱정하는 목소리가 있어요. 하지만 세계화는 지역의 문화가 세계로 퍼지는 통로도 돼요. 지역의 특성을 살리는 지역화와 글로컬 노력이 함께 일어나기 때문에, 세계는 연결되면서도 여전히 다양한 모자이크로 남아 있어요.","keywords":["세계화"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#f2","kind":"faq","title":"허브 공항은 왜 중요해요?","text":"많은 항공 노선이 모여 사람과 물건이 갈아타는 중심이 되기 때문이에요. 허브 공항이 있는 도시는 세계 여러 곳과 쉽게 이어져 관광·물류·국제회의 같은 활동이 활발해져요. 그래서 여러 나라가 자기 나라 공항을 허브 공항으로 키우려고 경쟁해요.","keywords":["허브 공항"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#m0","kind":"mistake","title":"자주 하는 실수","text":"\"중국과 일본 사이\", \"태평양과 맞닿음\"처럼 숫자가 없는 위치 설명을 절대적 위치로 고르는 실수 — 위도·경도로 나타낸 것만 절대적 위치예요. 주변과의 관계로 말하면 상대적 위치예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-01#m1","kind":"mistake","title":"자주 하는 실수","text":"종교·언어·산업을 자연환경으로 고르는 실수 — 사람이 만들어 온 것은 인문환경, 지형·기후처럼 사람이 만들지 않은 것은 자연환경이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-01","grade":"m1"},
{"id":"soc-m-1-02","kind":"unit","title":"아시아","text":"아시아의 자연환경, 종교와 문화, 인구, 산업의 특징을 살펴보고 우리나라와의 관계를 알아봐요. 아시아를 동·동남·남부·서남·중앙아시아로 나누고 주요 나라와 도시의 위치를 말할 수 있어요. 아시아의 지형과 기후(계절풍)의 특징을 설명할 수 있어요. 아시아의 여러 종교와 관련된 문화 경관·생활 양식을 구분하고, 종교의 공존과 갈등을 설명할 수 있어요. 아시아…","keywords":["계절풍(몬순)","히말라야산맥","문화 경관","모스크","할랄","인구 구조","저출산·고령화","플랜테이션","첨단 산업"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c0","kind":"concept","title":"아시아의 지역 구분과 주요 나라·도시","text":"아시아는 세계에서 가장 넓은 대륙이고, 세계 인구의 절반 이상이 살아요. 워낙 넓어서 자연환경과 문화가 비슷한 곳끼리 묶어 여러 지역으로 나누어 살펴봐요. 지역 · 주요 나라 · 주요 도시 동아시아 · 한국, 중국, 일본, 몽골 · 서울, 베이징, 도쿄 동남아시아 · 베트남, 태국, 인","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c1","kind":"concept","title":"아시아의 자연환경: 지형과 기후","text":"지형 — 아시아의 가운데에는 높고 험한 산지와 고원이 있어요. 세계에서 가장 높은 산들이 모인 히말라야산맥(가장 높은 에베레스트산은 해발 약 8,800 m가 넘어요)과 \"세계의 지붕\"이라 불리는 티베트고원이 대표적이에요. 이 높은 곳에서 큰 하천이 사방으로 흘러내려 하류에 넓은 평야를 ","keywords":["계절풍(몬순)","히말라야산맥"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c2","kind":"concept","title":"아시아의 종교와 생활","text":"세계의 큰 종교 가운데 불교·힌두교는 남부아시아(인도)에서, 이슬람교·크리스트교는 서남아시아에서 시작되었어요. 종교는 건물과 거리의 모습(문화 경관), 음식, 옷, 명절 같은 생활 양식에 큰 영향을 줘요. 종교 · 주로 믿는 곳 · 문화 경관과 생활 불교 · 동아시아, 동남아시아(태국·","keywords":["문화 경관","모스크"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c3","kind":"concept","title":"종교의 공존과 갈등","text":"여러 종교를 믿는 사람들이 한 나라, 한 도시에 함께 살면 서로 어울려 지내기도 하고 부딪치기도 해요. 공존 — 말레이시아와 싱가포르에는 이슬람교·불교·힌두교·크리스트교를 믿는 사람들이 함께 살아요. 여러 종교의 명절을 모두 공휴일로 정하고, 식당에서 할랄 음식을 따로 표시하는 등 서로","keywords":["할랄"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c4","kind":"concept","title":"아시아의 인구: 고령화 지역과 인구 증가 지역","text":"아시아에는 세계 인구의 약 60%가 살아요. 인도와 중국은 인구가 각각 14억 명 안팎으로 세계에서 인구가 가장 많은 두 나라예요. 사람들은 주로 계절풍의 영향으로 비가 넉넉한 큰 하천 하류의 평야에 모여 살고, 사막·높은 산지·시베리아에는 인구가 적어요. 인구 구조는 인구를 성별·나이","keywords":["인구 구조","저출산·고령화"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#c5","kind":"concept","title":"아시아의 산업과 우리나라","text":"아시아는 지역마다 발달한 산업이 달라요. 자원 생산: 서남아시아의 페르시아만 주변에는 석유와 천연가스가 많이 묻혀 있어 세계로 수출해요. 중앙아시아도 석유·천연가스·광물 자원이 풍부해요. 제조업: 동남아시아와 남부아시아는 일할 사람이 많고 임금이 비교적 낮아 옷·신발·전자 제품을 만드는","keywords":["플랜테이션","첨단 산업"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t0","kind":"term","title":"계절풍(몬순)","text":"계절에 따라 부는 방향이 바뀌는 바람이에요. 아시아에서는 여름에 바다에서 대륙으로, 겨울에 대륙에서 바다로 불어요.","keywords":["계절풍(몬순)"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t1","kind":"term","title":"히말라야산맥","text":"남부아시아와 티베트고원 사이에 있는, 세계에서 가장 높은 산들이 모인 산맥이에요. 가장 높은 산은 에베레스트산이에요.","keywords":["히말라야산맥"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t2","kind":"term","title":"문화 경관","text":"사람들이 자연에 손을 대어 만든 경관이에요. 사원·성당·모스크 같은 종교 건물, 논, 거리 모습 등이 있어요.","keywords":["문화 경관"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t3","kind":"term","title":"모스크","text":"이슬람교의 예배 건물이에요. 둥근 지붕과 뾰족한 탑(첨탑)이 있는 경우가 많아요.","keywords":["모스크"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t4","kind":"term","title":"할랄","text":"이슬람교의 율법에 따라 먹거나 쓰는 것이 허용된 음식·제품이에요. 돼지고기와 술은 할랄이 아니에요.","keywords":["할랄"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t5","kind":"term","title":"인구 구조","text":"인구를 성별·나이별로 나누어 본 모습이에요. 유소년층(0~14세)·청장년층(15~64세)·노년층(65세 이상)의 비율로 비교해요.","keywords":["인구 구조"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t6","kind":"term","title":"저출산·고령화","text":"태어나는 아이 수가 줄고(저출산), 전체 인구에서 노인 비율이 높아지는(고령화) 현상이에요.","keywords":["저출산·고령화"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t7","kind":"term","title":"플랜테이션","text":"열대 지역에서 기름야자·천연고무·커피 같은 작물 한 가지를 대규모로 길러 수출하는 농업이에요.","keywords":["플랜테이션"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#t8","kind":"term","title":"첨단 산업","text":"반도체·소프트웨어처럼 높은 기술과 많은 연구가 필요한 산업이에요.","keywords":["첨단 산업"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#f0","kind":"faq","title":"불교는 인도에서 시작됐다는데 왜 인도에는 힌두교를 믿는 사람이 더 많아요?","text":"불교는 인도에서 시작되었지만, 오랜 세월이 지나면서 인도에서는 힌두교가 다시 크게 퍼졌어요. 대신 불교는 동아시아와 동남아시아로 전해져 그곳에서 널리 믿게 되었어요. 종교가 시작된 곳과 오늘날 많이 믿는 곳이 꼭 같지는 않아요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#f1","kind":"faq","title":"이슬람교를 믿는 사람이 가장 많은 나라는 사우디아라비아 아니에요?","text":"아니에요. 이슬람교는 서남아시아(아라비아반도)에서 시작되었지만, 이슬람교를 믿는 사람이 가장 많은 나라는 동남아시아의 인도네시아예요. 인도네시아는 인구가 많고 그중 대부분이 이슬람교를 믿기 때문이에요. 상인들을 통해 이슬람교가 바닷길을 따라 동남아시아까지 퍼졌어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#f2","kind":"faq","title":"저출산·고령화가 왜 문제예요?","text":"아이가 적게 태어나면 시간이 지나 일할 수 있는 사람이 줄어들어요. 반대로 노인 인구는 늘어나 연금·의료·돌봄에 드는 비용이 커지지요. 일하는 사람 한 명이 책임져야 할 부담이 커지고, 학생이 줄어 문을 닫는 학교도 생겨요. 그래서 아이를 키우기 좋은 환경을 만들고 노인이 건강하게 일할 수 있게 돕는 노력이 필요해요.","keywords":["저출산·고령화"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#m0","kind":"mistake","title":"자주 하는 실수","text":"종교가 시작된 곳과 오늘날 많이 믿는 곳을 같다고 여기는 실수 — 불교는 인도에서 시작했지만 동아시아·동남아시아에서 많이 믿고, 이슬람교를 믿는 사람이 가장 많은 나라는 인도네시아예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-02#m1","kind":"mistake","title":"자주 하는 실수","text":"여름 계절풍과 겨울 계절풍의 방향을 거꾸로 기억하는 실수 — 여름에는 바다 → 대륙(덥고 습함, 비가 많음), 겨울에는 대륙 → 바다(차갑고 건조)예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-02","grade":"m1"},
{"id":"soc-m-1-03","kind":"unit","title":"유럽","text":"유럽의 자연환경과 도시를 살펴보고, 기후 위기에 대응하는 노력과 유럽 연합의 변화를 알아봐요. 유럽의 주요 나라·도시의 위치와 지형·기후의 특징을 설명할 수 있어요. 역사 도시·세계 도시·산업 도시 등 유럽 도시의 여러 유형을 구분할 수 있어요. 기후 위기에 대응하는 지속가능한 도시의 노력(친환경 교통·탄소 중립)을 설명할 수 있어요. 유럽 연합(EU)의…","keywords":["피오르","국제 하천","북대서양 해류","편서풍","서안 해양성 기후","지중해성 기후","세계 도시","탄소 중립","유럽 연합(EU)","유로화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c0","kind":"concept","title":"유럽의 주요 나라·도시와 지형","text":"유럽은 유라시아 대륙의 서쪽에 있어요. 면적은 넓지 않지만 여러 나라가 모여 있어요. 지역 · 주요 나라(도시) 서부 · 영국(런던), 프랑스(파리), 독일(베를린), 네덜란드(암스테르담), 벨기에(브뤼셀) 남부 · 이탈리아(로마), 스페인(마드리드), 그리스(아테네) 북부 · 노르웨이","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c1","kind":"concept","title":"유럽의 기후","text":"유럽은 우리나라보다 북쪽(대부분 북위 35°~70°)에 있지만, 서부 유럽은 위도에 비해 겨울이 따뜻한 편이에요. 런던(북위 약 51°)의 1월 평균 기온은 대략 5℃로, 서울(북위 약 37°)의 1월 평균 기온(대략 영하 2℃)보다 높아요. 까닭은 대서양을 따라 올라오는 따뜻한 바닷물","keywords":["북대서양 해류","편서풍","서안 해양성 기후","지중해성 기후"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c2","kind":"concept","title":"다양한 유형의 유럽 도시","text":"유럽의 도시는 오랜 역사와 산업, 국제 관계 속에서 저마다 다른 얼굴을 갖게 되었어요. 역사 도시: 오래된 건물과 유적이 많이 남아 있는 도시예요. 로마(이탈리아)의 고대 원형 경기장, 아테네(그리스)의 신전, 프라하(체코)의 옛 거리 등이 있어요. 옛 모습을 지키려고 새 건물의 높이와","keywords":["세계 도시"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c3","kind":"concept","title":"기후 위기와 지속가능한 도시","text":"지구 온난화가 심해지면서 폭염·가뭄·홍수·해수면 상승 같은 피해가 커지고 있어요. 이것을 기후 위기라고 해요. 온실가스는 주로 석탄·석유를 태우는 자동차, 공장, 건물 난방에서 나와요. 그래서 사람이 많이 모여 사는 도시가 바뀌어야 해요. 탄소 중립은 배출하는 온실가스의 양만큼 흡수하거","keywords":["탄소 중립"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c4","kind":"concept","title":"유럽 연합(EU)의 통합과 주민 생활","text":"두 차례 세계 대전을 겪은 유럽 나라들은 다시 전쟁을 막고 경제를 함께 키우려고 손을 잡았어요. 1952년 석탄과 철강을 함께 관리하는 기구에서 시작해 협력의 범위를 넓혔고, 1993년 유럽 연합(EU)이 출범했어요. 2020년 영국이 탈퇴한 뒤 회원국은 27개국이에요. 통합으로 바뀐 ","keywords":["유럽 연합(EU)","유로화"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#c5","kind":"concept","title":"유럽의 분리 움직임","text":"통합이 이어지는 한편, 따로 서려는 움직임도 있어요. 나라가 EU를 떠난 경우 — 영국의 탈퇴(브렉시트) 영국은 2016년 국민 투표에서 탈퇴를 고른 표가 더 많이 나와 2020년에 EU를 떠났어요. 탈퇴를 고른 사람들은 나라 스스로 법과 이민 정책을 정하기를 바랐고, 반대한 사람들은 ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t0","kind":"term","title":"피오르","text":"빙하가 깎아 만든 골짜기에 바닷물이 들어와 생긴 좁고 긴 만이에요. 노르웨이 해안에 많아요.","keywords":["피오르"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t1","kind":"term","title":"국제 하천","text":"여러 나라를 지나 흐르는 하천이에요. 예: 라인강, 도나우강","keywords":["국제 하천"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t2","kind":"term","title":"북대서양 해류","text":"대서양에서 서부 유럽 쪽으로 흐르는 따뜻한 바닷물의 흐름이에요. 서부 유럽의 겨울을 따뜻하게 해요.","keywords":["북대서양 해류"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t3","kind":"term","title":"편서풍","text":"중위도에서 1년 내내 서쪽에서 불어오는 바람이에요.","keywords":["편서풍"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t4","kind":"term","title":"서안 해양성 기후","text":"대륙 서쪽 해안에 나타나는 기후로, 겨울이 온화하고 여름이 서늘하며 1년 내내 비가 고르게 와요.","keywords":["서안 해양성 기후"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t5","kind":"term","title":"지중해성 기후","text":"여름은 덥고 건조하며 겨울은 따뜻하고 비가 오는 기후예요. 올리브·포도 같은 나무 작물을 길러요.","keywords":["지중해성 기후"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t6","kind":"term","title":"세계 도시","text":"다국적 기업 본사·금융 기관·국제기구가 모여 세계의 경제·정치·문화를 이끄는 도시예요. 예: 런던, 파리","keywords":["세계 도시"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t7","kind":"term","title":"탄소 중립","text":"배출하는 온실가스의 양만큼 흡수하거나 없애서 실제 배출량을 0으로 만드는 것이에요.","keywords":["탄소 중립"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t8","kind":"term","title":"유럽 연합(EU)","text":"1993년 출범한 유럽 여러 나라의 연합이에요. 회원국 사이에서 사람·상품·돈이 자유롭게 오가요.","keywords":["유럽 연합(EU)"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#t9","kind":"term","title":"유로화","text":"유럽 연합의 여러 회원국이 함께 쓰는 공동 화폐예요.","keywords":["유로화"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#f0","kind":"faq","title":"유럽은 우리나라보다 북쪽인데 왜 겨울이 덜 추워요?","text":"서부 유럽 앞바다에는 따뜻한 북대서양 해류가 흐르고, 1년 내내 서쪽에서 부는 편서풍이 따뜻한 바다의 공기를 대륙으로 실어 오기 때문이에요. 반대로 우리나라는 겨울에 차가운 대륙에서 부는 북서 계절풍의 영향을 받아 위도에 비해 추워요. 다만 바다에서 먼 유럽의 동부 내륙은 겨울이 매우 추워요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#f1","kind":"faq","title":"유럽 연합 나라는 모두 유로화를 써요?","text":"아니에요. 여러 회원국이 유로화를 쓰지만, 스웨덴·폴란드처럼 자기 나라 화폐를 계속 쓰는 회원국도 있어요. 반대로 유럽 연합 회원국이 아닌데 유로화를 쓰는 곳도 있어요.","keywords":["유로화"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#f2","kind":"faq","title":"지중해성 기후 지역은 왜 여름에 비가 안 와요?","text":"여름에는 비구름이 잘 생기지 않는 건조한 공기(고기압)가 지중해 쪽까지 올라와 머물러서 맑고 건조한 날이 이어져요. 겨울에는 이 건조한 공기가 남쪽으로 물러나고 편서풍이 비구름을 몰고 와서 비가 내려요. 그래서 맑은 여름 날씨를 즐기려는 관광객이 많이 찾아와요.","keywords":["지중해성 기후"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#m0","kind":"mistake","title":"자주 하는 실수","text":"지중해성 기후를 \"여름에 비가 많다\"고 거꾸로 기억하는 실수 — 지중해성 기후는 여름이 덥고 건조하고, 겨울에 비가 와요. 그래서 가뭄에 강한 올리브·포도를 길러요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-03#m1","kind":"mistake","title":"자주 하는 실수","text":"유럽 연합의 모든 회원국이 유로화를 쓴다고 생각하는 실수 — 자기 나라 화폐를 쓰는 회원국도 있어요. 영국도 회원국이었을 때 유로화를 쓰지 않았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-03","grade":"m1"},
{"id":"soc-m-1-04","kind":"unit","title":"아프리카","text":"아프리카의 자연환경과 다양한 문화, 발전 가능성을 탐구하며 아프리카에 대한 생각을 돌아봐요. 아프리카의 주요 나라·도시의 위치와 자연환경(사막·열대 우림·사바나·큰 하천)을 설명할 수 있어요. 자연환경과 역사에 따라 아프리카에 다양한 문화가 나타나는 까닭을 말할 수 있어요. 아프리카의 잠재력(자원·젊은 인구·성장하는 도시)을 알고, 아프리카에 대한 편견을…","keywords":["사하라 사막","사바나","열대 우림","오아시스","사막화","고원","식민 지배","아프리카 연합(AU)","공정 무역","지속가능한 발전"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c0","kind":"concept","title":"아프리카의 주요 나라와 도시","text":"아프리카는 아시아 다음으로 넓은 대륙이에요. 54개 나라가 있고, 인구는 14억 명이 넘어요(2023년 기준). 대륙 북부에 펼쳐진 사하라 사막을 경계로 북부 아프리카와 사하라 이남 아프리카로 나누어 보기도 해요. 지역 · 주요 나라(도시) 북부 · 이집트(카이로), 모로코, 알제리 서","keywords":["사하라 사막","아프리카 연합(AU)"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c1","kind":"concept","title":"아프리카의 지형과 큰 하천","text":"아프리카는 해안 가까이를 빼면 대체로 높고 평평한 고원이 넓게 펼쳐진 대륙이에요. 동아프리카 지구대: 땅이 갈라지며 생긴 길고 깊은 골짜기예요. 주변에 화산과 호수가 많아요. 킬리만자로산(탄자니아): 아프리카에서 가장 높은 산(해발 약 5,900 m)이에요. 적도 가까이에 있지만, 아주","keywords":["열대 우림","고원"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c2","kind":"concept","title":"아프리카의 기후와 경관: 열대 우림·사바나·사막","text":"적도가 아프리카 대륙의 가운데를 지나요. 그래서 적도를 중심으로 북쪽과 남쪽에 비슷한 기후가 차례로 나타나요. 열대 우림 → 사바나 → 초원(스텝) → 사막 → 지중해성 기후(북쪽 끝과 남쪽 끝) 경관 · 나타나는 곳 · 특징 열대 우림 · 적도 부근(콩고 분지 등) · 1년 내내 덥고","keywords":["사하라 사막","사바나","열대 우림","오아시스"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c3","kind":"concept","title":"지리적 특성에 따른 다양한 문화","text":"넓은 아프리카에는 수많은 민족이 살고, 쓰는 언어도 1,000개가 넘어요. 자연환경과 역사가 지역마다 달라 문화도 다양해요. 자연환경에 따른 생활 사막: 물과 풀을 찾아 가축과 함께 옮겨 다니는 유목을 하거나, 오아시스에서 대추야자를 기르는 오아시스 농업을 해요. 강한 햇볕과 모래바람을","keywords":["사바나","열대 우림","오아시스"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c4","kind":"concept","title":"아프리카의 잠재력과 편견 돌아보기","text":"아프리카는 \"미래의 대륙\"이라고 불릴 만큼 발전 가능성(잠재력)이 커요. 자원: 석유(나이지리아 등), 금·백금(남아프리카 공화국), 다이아몬드(보츠와나 등), 전기 자동차 배터리에 쓰이는 코발트(콩고 민주 공화국) 같은 자원이 풍부해요. 젊은 인구: 아프리카는 세계에서 젊은 인구의 비","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#c5","kind":"concept","title":"지속가능한 발전과 국제 협력","text":"아프리카에는 아직 빈곤, 깨끗한 물·전기 부족, 분쟁, 사막화 같은 과제가 남아 있어요. 이를 풀고 지속가능한 발전(미래 세대의 몫을 해치지 않으면서 지금의 삶을 낫게 하는 발전)을 이루려는 노력이 이어지고 있어요. 아프리카 스스로의 노력 아프리카 연합(AU): 2002년 출범한 아프리","keywords":["사막화","아프리카 연합(AU)","지속가능한 발전"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t0","kind":"term","title":"사하라 사막","text":"아프리카 북부에 펼쳐진 세계에서 가장 큰 열대 사막이에요.","keywords":["사하라 사막"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t1","kind":"term","title":"사바나","text":"우기와 건기가 뚜렷하고, 키 큰 풀이 자라는 초원에 나무가 드문드문 있는 열대 경관이에요.","keywords":["사바나"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t2","kind":"term","title":"열대 우림","text":"1년 내내 덥고 비가 많아 키 큰 나무가 빽빽하게 우거진 숲이에요.","keywords":["열대 우림"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t3","kind":"term","title":"오아시스","text":"사막에서 물이 솟아 나오는 곳이에요. 주변에 마을과 밭이 생겨요.","keywords":["오아시스"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t4","kind":"term","title":"사막화","text":"가뭄과 지나친 방목·나무 베기 등으로 땅이 사막처럼 메말라 가는 현상이에요. 사헬 지대에서 심해요.","keywords":["사막화"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t5","kind":"term","title":"고원","text":"높은 곳에 넓고 평평하게 펼쳐진 땅이에요. 아프리카는 고원이 넓은 대륙이에요.","keywords":["고원"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t6","kind":"term","title":"식민 지배","text":"힘이 센 나라가 다른 지역을 강제로 다스리는 것이에요. 아프리카의 많은 나라가 19세기 말부터 유럽 나라의 식민 지배를 받았어요.","keywords":["식민 지배"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t7","kind":"term","title":"아프리카 연합(AU)","text":"2002년 출범한 아프리카 나라들의 연합이에요. 본부는 에티오피아의 아디스아바바에 있어요.","keywords":["아프리카 연합(AU)"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t8","kind":"term","title":"공정 무역","text":"생산자에게 정당한 값을 치르고 물건을 사는 무역이에요. 예: 공정 무역 커피·초콜릿","keywords":["공정 무역"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#t9","kind":"term","title":"지속가능한 발전","text":"미래 세대가 쓸 환경과 자원을 해치지 않으면서 지금의 삶을 낫게 하는 발전이에요.","keywords":["지속가능한 발전"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#f0","kind":"faq","title":"아프리카는 다 더워요?","text":"아니에요. 적도 부근의 낮은 땅은 1년 내내 덥지만, 나이로비·아디스아바바 같은 고원 도시는 높은 곳에 있어 1년 내내 온화해요. 킬리만자로산 꼭대기에는 눈과 빙하가 있고, 아프리카 남쪽 끝과 북쪽 끝은 겨울이 쌀쌀한 지중해성 기후예요. 사막도 밤에는 꽤 추워요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#f1","kind":"faq","title":"왜 아프리카 나라들은 영어나 프랑스어를 써요?","text":"19세기 말부터 영국·프랑스·포르투갈 같은 유럽 나라의 식민 지배를 받았기 때문이에요. 한 나라 안에 여러 민족이 각자의 언어를 쓰다 보니, 독립한 뒤에도 서로 통하는 말로 유럽 언어를 공용어로 삼은 나라가 많아요. 물론 스와힐리어처럼 아프리카에서 생겨나 널리 쓰이는 언어도 많아요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#f2","kind":"faq","title":"아프리카를 \"미래의 대륙\"이라고 부르는 이유가 뭐예요?","text":"석유·코발트·금 같은 자원이 풍부하고, 젊은 인구의 비율이 세계에서 가장 높으며, 도시가 빠르게 커지면서 큰 시장이 생기고 있기 때문이에요. 휴대 전화 금융처럼 새로운 기술을 빠르게 받아들이는 모습도 그 까닭이에요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#m0","kind":"mistake","title":"자주 하는 실수","text":"아프리카를 하나의 나라처럼 말하는 실수 — 아프리카는 54개 나라가 있는 대륙이에요. \"아프리카 사람들은 모두 ~해요\" 같은 말은 편견이 되기 쉬워요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-04#m1","kind":"mistake","title":"자주 하는 실수","text":"사바나와 열대 우림을 헷갈리는 실수 — 1년 내내 비가 많아 나무가 빽빽하면 열대 우림, 우기와 건기가 나뉘고 풀밭에 나무가 드문드문 있으면 사바나예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-04","grade":"m1"},
{"id":"soc-m-1-05","kind":"unit","title":"아메리카","text":"아메리카의 자연환경과 다양한 민족·문화를 살펴보고, 초국적 기업이 지역에 미치는 영향을 분석해요. 아메리카의 주요 나라·도시의 위치와 산맥·강·평원 같은 자연환경을 설명할 수 있어요. 아메리카의 인구가 여러 민족(인종)으로 이루어진 까닭을 이주의 역사로 설명할 수 있어요. 언어·종교·음식·음악에서 문화 혼종성의 사례를 찾을 수 있어요. 초국적 기업의 생산…","keywords":["앵글로아메리카","라틴아메리카","안데스산맥","아마존강","메스티소","플랜테이션","문화 혼종성","초국적 기업","공간적 분업","산업 공동화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c0","kind":"concept","title":"아메리카의 위치와 주요 나라·도시","text":"아메리카는 태평양과 대서양 사이에 남북으로 길게 뻗은 대륙이에요. 좁은 땅(중앙아메리카)을 사이에 두고 북아메리카와 남아메리카로 나뉘어요. 파나마의 좁은 땅에는 태평양과 대서양을 잇는 파나마 운하가 있어 배가 남아메리카를 빙 돌아가지 않아도 돼요. 지역 · 주요 나라 · 주요 도시 북아","keywords":["앵글로아메리카"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c1","kind":"concept","title":"아메리카의 자연환경: 서쪽의 높은 산맥, 가운데의 넓은 평원","text":"아메리카의 지형은 서쪽에 높고 험한 산맥, 가운데에 넓은 평야, 동쪽에 낮은 산지나 고원이 있는 모습이 북아메리카와 남아메리카에서 비슷하게 나타나요. 로키산맥: 북아메리카 서쪽을 남북으로 달리는 높고 험한 산맥이에요. 안데스산맥: 남아메리카 서쪽 해안을 따라 남북으로 길게 뻗은 산맥으로","keywords":["안데스산맥","아마존강"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c2","kind":"concept","title":"여러 민족(인종)이 함께 사는 아메리카","text":"아메리카에는 여러 민족(인종)이 함께 살아요. 오랜 이주의 역사 때문이에요. 원주민: 아주 오래전 아시아에서 건너온 것으로 여겨지는 사람들이 아메리카 곳곳에 살았어요. 안데스산맥의 잉카, 멕시코의 아스테카 같은 문명을 이루었어요. 유럽인: 16세기 무렵부터 유럽 사람들이 건너와 식민지를","keywords":["앵글로아메리카","라틴아메리카","안데스산맥","메스티소","플랜테이션"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c3","kind":"concept","title":"문화 혼종성: 섞여서 새로워진 아메리카의 문화","text":"서로 다른 문화가 만나 섞이면서 원래 어느 문화와도 다른 새로운 문화가 만들어지는 것을 문화 혼종성이라고 해요. 여러 민족이 함께 사는 아메리카에서 잘 나타나요. 분야 · 사례 언어 · 라틴아메리카는 대부분 에스파냐어를 쓰지만 브라질은 포르투갈어를 써요. 캐나다의 퀘벡주에서는 프랑스어를","keywords":["라틴아메리카","문화 혼종성"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c4","kind":"concept","title":"초국적 기업과 글로벌 생산 체제","text":"초국적 기업은 여러 나라에 본사·연구소·공장·판매 지사를 두고 세계를 무대로 활동하는 기업이에요. 이런 기업은 각 기능을 가장 유리한 곳에 따로 나누어 두어요(공간적 분업). 기능 · 주로 들어서는 곳 · 까닭 본사 · 선진국의 대도시 · 자본과 정보가 모이고, 중요한 결정을 내리기 좋","keywords":["초국적 기업","공간적 분업"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#c5","kind":"concept","title":"공장의 해외 이전과 지역의 변화","text":"초국적 기업이 생산 공장을 다른 나라로 옮기면, 공장이 들어선 지역과 떠난 지역 모두 크게 바뀌어요. 공장이 들어선 지역 좋은 점: 일자리가 늘고, 기술을 배우고, 도로·항만 같은 시설이 생겨 경제가 성장해요. 문제점: 이익의 많은 부분이 본사가 있는 나라로 빠져나가요. 오염 물질이 늘","keywords":["초국적 기업","산업 공동화"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t0","kind":"term","title":"앵글로아메리카","text":"리오그란데강 북쪽의 미국·캐나다 지역이에요. 영국 등 유럽 북서부의 영향을 많이 받아 영어를 주로 써요.","keywords":["앵글로아메리카"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t1","kind":"term","title":"라틴아메리카","text":"리오그란데강 남쪽의 멕시코·중앙아메리카·남아메리카 지역이에요. 에스파냐·포르투갈의 영향을 받아 에스파냐어·포르투갈어를 주로 써요.","keywords":["라틴아메리카"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t2","kind":"term","title":"안데스산맥","text":"남아메리카 서쪽을 따라 남북으로 길게 뻗은 높고 험한 산맥이에요. 세계에서 가장 긴 산맥이에요.","keywords":["안데스산맥"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t3","kind":"term","title":"아마존강","text":"남아메리카 적도 부근을 흐르는 강으로, 유역 면적이 세계에서 가장 넓어요. 주변에 넓은 열대 우림이 있어요.","keywords":["아마존강"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t4","kind":"term","title":"메스티소","text":"유럽인과 아메리카 원주민 사이의 혼혈이에요. 멕시코 등 여러 라틴아메리카 나라에서 비율이 높아요.","keywords":["메스티소"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t5","kind":"term","title":"플랜테이션","text":"선진국의 자본·기술과 현지의 값싼 노동력으로 사탕수수·커피 같은 작물 한 가지를 대규모로 기르는 농업이에요.","keywords":["플랜테이션"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t6","kind":"term","title":"문화 혼종성","text":"서로 다른 문화가 만나 섞이면서 새로운 문화가 만들어지는 성질이에요. 예: 재즈, 탱고, 멕시코의 죽은 자의 날","keywords":["문화 혼종성"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t7","kind":"term","title":"초국적 기업","text":"여러 나라에 본사·연구소·공장·판매 지사를 두고 세계를 무대로 활동하는 기업이에요.","keywords":["초국적 기업"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t8","kind":"term","title":"공간적 분업","text":"기업이 본사·연구소·생산 공장 같은 기능을 각각 유리한 곳에 나누어 두는 것이에요.","keywords":["공간적 분업"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#t9","kind":"term","title":"산업 공동화","text":"공장이 다른 지역이나 나라로 빠져나가 그 지역의 산업이 비고 일자리가 줄어드는 현상이에요.","keywords":["산업 공동화"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#f0","kind":"faq","title":"왜 '라틴'아메리카라고 불러요?","text":"라틴아메리카 사람들이 주로 쓰는 에스파냐어와 포르투갈어가 옛 로마의 말인 라틴어에서 갈라져 나온 언어이기 때문이에요. 그래서 이 언어를 쓰는 에스파냐·포르투갈의 영향을 받은 지역을 라틴아메리카라고 불러요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#f1","kind":"faq","title":"멕시코는 북아메리카예요, 라틴아메리카예요?","text":"둘 다 맞아요. 기준이 달라요. 위치로 나누면 멕시코는 북아메리카에 있어요. 문화로 나누면 에스파냐어를 쓰고 가톨릭 신자가 많은 라틴아메리카에 속해요.","keywords":["라틴아메리카"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#f2","kind":"faq","title":"초국적 기업의 공장이 들어오면 좋은 거예요, 나쁜 거예요?","text":"한쪽으로만 말하기 어려워요. 일자리가 늘고 기술을 배우며 경제가 성장하는 좋은 점이 있지만, 이익이 해외로 빠져나가거나 환경 오염·낮은 임금 같은 문제가 생길 수도 있어요. 그래서 좋은 점은 살리고 문제점은 줄이는 방법을 함께 찾는 것이 중요해요.","keywords":["초국적 기업"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#m0","kind":"mistake","title":"자주 하는 실수","text":"로키산맥과 안데스산맥을 헷갈리는 실수 — 북아메리카 서쪽은 로키산맥, 남아메리카 서쪽은 안데스산맥이에요. 둘 다 대륙의 서쪽에 있어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#m1","kind":"mistake","title":"자주 하는 실수","text":"메스티소와 물라토를 헷갈리는 실수 — 유럽인+원주민은 메스티소, 유럽인+아프리카인은 물라토예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-05#m2","kind":"mistake","title":"자주 하는 실수","text":"멕시코를 위치로도 라틴아메리카라서 남아메리카라고 하는 실수 — 위치는 북아메리카, 문화는 라틴아메리카예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-05","grade":"m1"},
{"id":"soc-m-1-06","kind":"unit","title":"오세아니아와 극지방","text":"오세아니아의 자연환경과 자원, 태평양의 환경 문제, 극지방을 둘러싼 이해관계를 알아봐요. 오세아니아의 주요 나라·도시의 위치와 자연환경을 설명할 수 있어요. 오세아니아가 자원 수출로 세계, 특히 아시아와 어떻게 연결되는지 설명할 수 있어요. 태평양의 해양 쓰레기와 해수면 상승 문제를 알고, 해결에 참여하는 방법을 찾을 수 있어요. 극지방의 지리적 중요성과…","keywords":["오세아니아","남반구","산호초 섬","노천 채굴","미세 플라스틱","해수면 상승","북극 항로","남극 조약","이해관계"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c0","kind":"concept","title":"오세아니아의 위치와 주요 나라·도시","text":"오세아니아는 오스트레일리아 대륙과 뉴질랜드, 그리고 태평양에 흩어진 수많은 섬들을 함께 이르는 말이에요. 대부분 적도 남쪽의 남반구에 있어서 우리나라와 계절이 반대예요. 우리나라가 겨울인 12월에 오스트레일리아는 여름이에요. 나라 · 수도 · 큰 도시 오스트레일리아 · 캔버라 · 시드니","keywords":["오세아니아","남반구"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c1","kind":"concept","title":"오세아니아의 자연환경","text":"오스트레일리아는 오래되고 평탄한 땅이 넓어요. 동쪽에는 낮은 산지(그레이트디바이딩산맥)가 남북으로 뻗어 있고, 북동쪽 바다에는 세계에서 가장 큰 산호초 지대인 그레이트배리어리프가 있어요. 안쪽의 건조한 초원에서는 지하수를 끌어 올려 양과 소를 대규모로 길러요. 뉴질랜드는 북섬과 남섬으로","keywords":["오세아니아","산호초 섬"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c2","kind":"concept","title":"자원 수출로 본 오세아니아와 세계의 연결","text":"오세아니아는 땅이 넓고 자원이 풍부하지만 인구가 적어요. 그래서 자원과 농축산물을 많이 생산해 다른 나라에 수출해요. 오스트레일리아: 철광석·석탄을 세계에서 손꼽히게 많이 수출하고, 천연가스·보크사이트 등도 수출해요. 땅 위에서 바로 파 들어가는 노천 채굴로 캐는 곳이 많아요. 밀·소고","keywords":["오세아니아","남반구","노천 채굴"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c3","kind":"concept","title":"태평양의 환경 문제와 해결 참여","text":"태평양은 세계에서 가장 큰 바다지만 여러 환경 문제를 겪고 있어요. 해양 쓰레기: 육지와 배에서 버려진 플라스틱 쓰레기가 해류를 따라 떠돌다가 한곳에 모여 커다란 쓰레기 섬(쓰레기 지대)을 이루기도 해요. 플라스틱은 잘 썩지 않고 잘게 부서져 미세 플라스틱이 돼요. 바다 생물이 이를 먹","keywords":["산호초 섬","미세 플라스틱","해수면 상승"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c4","kind":"concept","title":"극지방의 지리적 중요성","text":"극지방은 북극과 남극 주변의 아주 추운 지역이에요. · 북극 · 남극 모습 · 북극해라는 바다가 대부분 얼어 있고, 주변을 대륙이 둘러싸요 · 두꺼운 얼음(빙하)으로 덮인 대륙이에요 사는 사람 · 이누이트 같은 원주민이 살아요 · 원래 사는 사람이 없고, 과학 기지 연구원이 머물러요 극","keywords":["북극 항로"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#c5","kind":"concept","title":"극지방 개발을 둘러싼 이해관계","text":"극지방의 가치가 커지면서 여러 나라와 사람들의 이해관계(서로 얻고 잃는 것)가 부딪쳐요. 북극: 러시아·캐나다·미국·노르웨이·덴마크(그린란드) 등 북극해를 둘러싼 나라들이 바다의 경계와 자원을 두고 경쟁해요. 다른 나라들도 항로와 자원에 관심이 커요. 남극: 1959년에 맺은 남극 조약","keywords":["남극 조약","이해관계"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t0","kind":"term","title":"오세아니아","text":"오스트레일리아 대륙, 뉴질랜드, 태평양의 수많은 섬을 함께 이르는 말이에요. 대부분 남반구에 있어요.","keywords":["오세아니아"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t1","kind":"term","title":"남반구","text":"적도를 기준으로 지구의 남쪽 절반이에요. 북반구와 계절이 반대예요.","keywords":["남반구"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t2","kind":"term","title":"산호초 섬","text":"산호가 쌓여 만들어진 섬이에요. 낮고 평평해서 해수면 상승에 약해요.","keywords":["산호초 섬"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t3","kind":"term","title":"노천 채굴","text":"땅속 깊이 굴을 파지 않고, 땅 위에서 바로 파 들어가며 광물을 캐는 방법이에요.","keywords":["노천 채굴"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t4","kind":"term","title":"미세 플라스틱","text":"플라스틱이 잘게 부서져 생긴 아주 작은 조각이에요. 바다 생물의 몸에 쌓여 먹이 사슬을 따라 옮겨 가요.","keywords":["미세 플라스틱"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t5","kind":"term","title":"해수면 상승","text":"지구 온난화로 빙하가 녹고 바닷물의 부피가 늘어 바닷물 높이가 올라가는 현상이에요.","keywords":["해수면 상승"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t6","kind":"term","title":"북극 항로","text":"북극해를 지나 아시아와 유럽을 잇는 바닷길이에요. 수에즈 운하를 지나는 길보다 짧아요.","keywords":["북극 항로"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t7","kind":"term","title":"남극 조약","text":"1959년에 맺은 국제 약속이에요. 남극을 평화적 목적과 과학 연구에만 쓰고 군사 활동을 금지했어요.","keywords":["남극 조약"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#t8","kind":"term","title":"이해관계","text":"어떤 일에 대해 서로 얻는 것과 잃는 것이 걸려 있는 관계예요.","keywords":["이해관계"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#f0","kind":"faq","title":"오스트레일리아는 섬이에요, 대륙이에요?","text":"오스트레일리아는 대륙으로 분류해요. 사방이 바다로 둘러싸여 있지만 땅이 아주 넓어서, 세계에서 가장 작은 대륙으로 봐요. 그린란드처럼 그보다 작은 땅은 섬이라고 해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#f1","kind":"faq","title":"북극곰과 펭귄이 같은 곳에 살아요?","text":"아니에요. 북극곰은 북극에, 펭귄은 주로 남반구에 살아요. 남극에는 여러 종류의 펭귄이 살지만 북극곰은 없어요. 북극과 남극은 지구의 정반대 쪽에 있어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#f2","kind":"faq","title":"바다에 떠 있는 얼음이 녹아도 해수면이 올라가요?","text":"물에 떠 있는 얼음(바다 얼음)은 녹아도 해수면을 거의 올리지 않아요. 컵에 띄운 얼음이 녹아도 물이 넘치지 않는 것과 같아요. 해수면을 크게 올리는 것은 육지 위의 빙하가 녹아 바다로 흘러드는 것과, 바닷물이 따뜻해져 부피가 늘어나는 것이에요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#m0","kind":"mistake","title":"자주 하는 실수","text":"오스트레일리아의 수도를 시드니라고 하는 실수 — 가장 큰 도시는 시드니지만 수도는 캔버라예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-06#m1","kind":"mistake","title":"자주 하는 실수","text":"남극과 북극을 바꾸어 기억하는 실수 — 남극은 빙하로 덮인 대륙, 북극은 얼어 있는 바다(북극해)가 중심이에요. 남극 조약은 남극에 관한 약속이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-06","grade":"m1"},
{"id":"soc-m-1-07","kind":"unit","title":"인간과 사회생활","text":"사회화와 정체성, 지위와 역할을 이해하고 사회 속 갈등과 차별에 대처하는 자세를 생각해요. 사회화의 의미를 알고, 가정·학교·또래 집단·대중 매체 같은 사회화 기관의 역할을 설명할 수 있어요. 사회화 과정에서 자아 정체성이 만들어지는 과정을 설명할 수 있어요. 귀속 지위와 성취 지위를 구별하고, 역할 갈등의 사례와 대응 방법을 말할 수 있어요. 사회 집단…","keywords":["사회화","재사회화","사회화 기관","자아 정체성","귀속 지위","성취 지위","역할","역할 갈등","편견","차별"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c0","kind":"concept","title":"사회화: 사회 구성원이 되어 가는 과정","text":"사람은 태어날 때 말하는 법도, 인사하는 법도 몰라요. 다른 사람들과 함께 지내면서 하나씩 배워 가지요. 이처럼 사회 구성원으로 살아가는 데 필요한 언어, 지식, 규범, 가치, 행동 방식을 배워 가는 과정을 사회화라고 해요. 사회화를 통해 사람은 그 사회의 생활 방식을 익히고 사회적 존","keywords":["사회화","재사회화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c1","kind":"concept","title":"사회화 기관: 가정·학교·또래 집단·대중 매체","text":"사회화가 이루어지도록 돕는 사람이나 집단을 사회화 기관이라고 해요. 사회화 기관 · 하는 일 가정 · 처음 만나는 사회화 기관이에요. 말, 기본 생활 습관, 예절처럼 살아가는 데 기초가 되는 것을 배워요. 학교 · 지식과 기술, 사회 규범을 계획적이고 체계적으로 가르쳐요. 또래 집단 ·","keywords":["사회화","사회화 기관"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c2","kind":"concept","title":"사회화와 자아 정체성","text":"자아 정체성은 \"나는 어떤 사람인가\", \"나는 무엇을 중요하게 여기는가\"에 대해 스스로 갖는 일관된 생각이에요. 자아 정체성은 혼자 만들어지지 않아요. 가족·친구·선생님과 주고받는 말과 행동, 다른 사람이 나에게 거는 기대와 평가를 거치며, 곧 사회화 과정 속에서 조금씩 만들어져요. 예","keywords":["사회화","자아 정체성"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c3","kind":"concept","title":"사회적 지위: 귀속 지위와 성취 지위","text":"사람은 여러 집단에 속해 있고, 집단마다 차지하는 위치가 있어요. 이것을 사회적 지위라고 해요. 한 사람은 동시에 여러 지위를 가져요. 예를 들어 서준이는 집에서는 아들이자 형, 학교에서는 학생이자 반장, 동네 축구 동아리에서는 회원이에요. 지위는 얻는 방법에 따라 두 가지로 나뉘어요.","keywords":["귀속 지위","성취 지위"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c4","kind":"concept","title":"역할과 역할 갈등","text":"지위에는 그에 맞게 기대되는 행동이 있어요. 이것을 역할이라고 해요. 학생에게는 수업에 성실히 참여하는 것, 반장에게는 학급 일을 이끄는 것이 기대되지요. 같은 역할이라도 사람마다 실제로 하는 행동은 달라요. 이를 역할 행동이라고 해요. 역할 행동을 잘하면 칭찬·상 같은 보상을, 잘하지","keywords":["역할","역할 갈등"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#c5","kind":"concept","title":"사회 집단 사이의 갈등, 편견과 차별","text":"사회 집단은 둘 이상의 사람이 소속감을 갖고 서로 영향을 주고받는 모임이에요. 가족, 학급, 동아리, 지역 사회, 세대, 민족 등이 있어요. 집단마다 이익과 생각이 달라서 집단 사이의 갈등이 생기기도 해요. 갈등을 키우는 것이 편견과 차별이에요. 고정 관념: 어떤 집단의 사람들은 모두 ","keywords":["편견","차별"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t0","kind":"term","title":"사회화","text":"사회 구성원으로 살아가는 데 필요한 언어, 지식, 규범, 가치, 행동 방식을 배워 가는 과정이에요. 평생 이루어져요.","keywords":["사회화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t1","kind":"term","title":"재사회화","text":"새로운 환경에 적응하려고 그에 맞는 생활 방식을 새로 배우는 것이에요. 예: 이민 간 사람이 새 나라의 말과 생활을 배우기","keywords":["재사회화"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t2","kind":"term","title":"사회화 기관","text":"사회화가 이루어지도록 돕는 사람이나 집단이에요. 가정, 학교, 또래 집단, 대중 매체 등이 있어요.","keywords":["사회화 기관"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t3","kind":"term","title":"자아 정체성","text":"\"나는 어떤 사람인가\"에 대해 스스로 갖는 일관된 생각이에요.","keywords":["자아 정체성"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t4","kind":"term","title":"귀속 지위","text":"태어나면서 저절로 갖게 되는 지위예요. 예: 아들, 딸, 남자, 여자","keywords":["귀속 지위"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t5","kind":"term","title":"성취 지위","text":"자신의 노력이나 선택으로 얻는 지위예요. 예: 학생, 반장, 교사","keywords":["성취 지위"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t6","kind":"term","title":"역할","text":"어떤 지위에 있는 사람에게 기대되는 행동이에요. 예: 반장의 역할은 학급 일을 이끄는 것","keywords":["역할"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t7","kind":"term","title":"역할 갈등","text":"한 사람이 가진 여러 지위의 역할이 동시에 요구되어 서로 부딪치는 것이에요.","keywords":["역할 갈등"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t8","kind":"term","title":"편견","text":"충분한 근거 없이 어떤 집단이나 사람을 부정적으로 판단하는 생각과 태도예요.","keywords":["편견"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#t9","kind":"term","title":"차별","text":"성별·나이·장애·출신 같은 정당하지 않은 까닭으로 어떤 사람을 불리하게 대하는 것이에요.","keywords":["차별"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#f0","kind":"faq","title":"학생은 왜 성취 지위예요? 그 나이가 되면 다 학교에 가잖아요.","text":"학생은 학교에 입학해야 얻는 지위예요. 태어나기만 하면 저절로 갖게 되는 딸·아들과는 달라요. 그래서 교과서에서는 학생을 성취 지위로 나눠요. 귀속 지위인지 성취 지위인지는 \"태어나면서 저절로 갖게 되었나?\"를 기준으로 따져요.","keywords":["성취 지위"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#f1","kind":"faq","title":"편견과 차별은 어떻게 달라요?","text":"편견은 마음속의 생각과 태도이고, 차별은 그것이 행동으로 나타난 거예요. \"그 사람들은 다 그래\"라고 생각하는 것은 편견, 그 생각 때문에 기회를 주지 않거나 따돌리는 것은 차별이에요.","keywords":["편견","차별"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#f2","kind":"faq","title":"역할 갈등은 나쁜 거예요?","text":"여러 지위를 가진 사람이라면 누구나 겪을 수 있는 자연스러운 일이에요. 중요한 것은 갈등을 어떻게 다루느냐예요. 우선순위를 정하고, 관련된 사람과 대화하며 도움을 받으면 잘 풀어 갈 수 있어요.","keywords":["역할","역할 갈등"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#m0","kind":"mistake","title":"자주 하는 실수","text":"귀속 지위와 성취 지위를 헷갈리는 실수 — \"태어나면서 저절로\" 갖게 되면 귀속 지위(딸, 형, 손자), \"노력이나 선택으로\" 얻으면 성취 지위(학생, 반장, 남편)예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#m1","kind":"mistake","title":"자주 하는 실수","text":"편견과 차별을 같은 것으로 보는 실수 — 편견은 생각·태도, 차별은 행동이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-07#m2","kind":"mistake","title":"자주 하는 실수","text":"재사회화를 \"처음 배우는 것\"으로 아는 실수 — 재사회화는 새로운 환경에 맞추어 다시 배우는 것이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-07","grade":"m1"},
{"id":"soc-m-1-08","kind":"unit","title":"다양한 문화의 이해","text":"문화의 의미와 특징을 알고, 미디어 속 문화를 비판적으로 보며 바람직한 문화 이해 태도를 길러요. 문화의 의미를 알고, 공유성·학습성·축적성·변동성·전체성의 특징을 사례로 설명할 수 있어요. 미디어를 통해 접하는 문화와 정보를 비판적으로 살펴볼 수 있어요. 자문화 중심주의·문화 사대주의·문화 상대주의를 구별하고, 바람직한 태도를 말할 수 있어요. 다문화 …","keywords":["문화","공유성","학습성","축적성","변동성","전체성","미디어 리터러시","자문화 중심주의","문화 상대주의","보편 윤리"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c0","kind":"concept","title":"문화란 무엇일까?","text":"\"문화\"라는 말은 두 가지 뜻으로 쓰여요. 좁은 뜻의 문화: 음악회·미술관처럼 교양이나 예술과 관련된 것이에요. \"문화생활을 즐긴다\"고 할 때의 문화예요. 넓은 뜻의 문화: 한 사회의 구성원들이 함께 만들고 나누는 생활 방식 전체예요. 먹고 입고 사는 모습(의식주), 언어, 종교, 예절","keywords":["문화"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c1","kind":"concept","title":"문화의 특징 ①: 공유성·학습성·축적성","text":"문화에는 몇 가지 공통된 특징이 있어요. 공유성: 문화는 한 사회의 구성원들이 함께 가지고 있어요. 그래서 같은 문화를 가진 사람끼리는 서로의 행동을 이해하고 예측할 수 있어요. 예: 우리나라 사람은 고개를 숙이며 인사하면 반갑다는 뜻임을 모두 알아요. 학습성: 문화는 태어날 때부터 가","keywords":["문화","공유성","학습성","축적성"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c2","kind":"concept","title":"문화의 특징 ②: 변동성·전체성","text":"변동성: 문화는 고정되어 있지 않고 시간이 흐르면서 변해요. 새로운 것이 발명되거나, 다른 사회의 문화가 들어오면서 새 요소가 더해지고, 오래된 요소는 사라지기도 해요. 예: 예전에는 손으로 편지를 써서 소식을 전했지만, 지금은 휴대 전화로 문자 메시지를 주고받아요. 전체성: 문화의 여","keywords":["문화","변동성","전체성"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c3","kind":"concept","title":"미디어 속 문화와 미디어 리터러시","text":"우리는 다른 나라에 직접 가 보지 않아도 텔레비전, 영화, 인터넷, 누리 소통망(SNS) 같은 미디어를 통해 다양한 문화를 만나요. 미디어 덕분에 세계의 문화를 쉽고 빠르게 접할 수 있지요. 하지만 미디어 속 문화는 있는 그대로의 전부가 아니에요. 미디어를 만드는 사람은 보여 줄 장면을","keywords":["문화","미디어 리터러시"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c4","kind":"concept","title":"문화를 이해하는 태도","text":"다른 문화를 바라보는 태도는 크게 세 가지로 나눌 수 있어요. 태도 · 뜻 · 문제점 또는 의미 자문화 중심주의 · 자기 문화만 우수하다고 여기고, 다른 문화를 낮게 보는 태도 · 구성원을 하나로 묶는 데 도움이 될 수 있지만, 다른 문화를 무시해 갈등이 생기고 좋은 점을 배우지 못해 ","keywords":["문화","자문화 중심주의","문화 상대주의"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#c5","kind":"concept","title":"다문화 사회: 문화 다양성 존중과 보편 윤리","text":"다문화 사회는 서로 다른 문화를 가진 사람들이 함께 어울려 사는 사회예요. 우리나라에도 일하러 온 외국인 노동자, 결혼 이민자, 유학생, 북한 이탈 주민 등 다양한 배경을 가진 사람들이 함께 살고 있어요. 다문화 사회에서는 문화 다양성을 존중하는 자세가 중요해요. 다른 문화를 가진 이웃","keywords":["문화","문화 상대주의","보편 윤리"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t0","kind":"term","title":"문화","text":"한 사회의 구성원들이 함께 만들고 나누는 생활 방식 전체예요. 의식주, 언어, 종교, 예절, 가치관 등을 포함해요.","keywords":["문화"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t1","kind":"term","title":"공유성","text":"문화를 한 사회의 구성원들이 함께 가지고 있다는 특징이에요. 그래서 서로의 행동을 이해하고 예측할 수 있어요.","keywords":["공유성"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t2","kind":"term","title":"학습성","text":"문화는 태어날 때부터 가진 것이 아니라 태어난 뒤 배워서 익힌다는 특징이에요.","keywords":["학습성"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t3","kind":"term","title":"축적성","text":"문화가 언어·문자 등을 통해 다음 세대로 전해지면서 쌓이고 풍부해진다는 특징이에요.","keywords":["축적성"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t4","kind":"term","title":"변동성","text":"문화가 시간이 흐르면서 새로운 요소가 더해지거나 사라지며 변한다는 특징이에요.","keywords":["변동성"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t5","kind":"term","title":"전체성","text":"문화의 요소들이 서로 연결되어 있어서 한 요소가 바뀌면 다른 요소도 함께 바뀐다는 특징이에요.","keywords":["전체성"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t6","kind":"term","title":"미디어 리터러시","text":"미디어가 전하는 정보를 비판적으로 이해하고 평가하며, 책임 있게 활용하고 만드는 능력이에요.","keywords":["미디어 리터러시"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t7","kind":"term","title":"자문화 중심주의","text":"자기 문화만 우수하다고 여기고 다른 문화를 낮게 보는 태도예요.","keywords":["자문화 중심주의"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t8","kind":"term","title":"문화 상대주의","text":"각 문화를 그 사회의 자연환경, 역사, 사회적 상황 속에서 이해하려는 태도예요.","keywords":["문화 상대주의"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#t9","kind":"term","title":"보편 윤리","text":"시대와 사회가 달라도 모든 사람이 지켜야 할 도덕 원칙이에요. 인간의 존엄성, 생명 존중, 자유와 평등 같은 가치예요.","keywords":["보편 윤리"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#f0","kind":"faq","title":"문화 상대주의면 모든 문화를 다 인정해야 하는 거 아니에요?","text":"아니에요. 문화 상대주의는 다른 문화를 그 사회의 맥락에서 이해하려는 태도예요. 하지만 사람의 생명과 존엄성, 자유를 해치는 관습까지 인정하는 것은 극단적 문화 상대주의라서 경계해야 해요. 그때 기준이 보편 윤리예요.","keywords":["문화","문화 상대주의"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#f1","kind":"faq","title":"학습성과 축적성은 어떻게 구별해요?","text":"학습성은 한 사람이 태어난 뒤 문화를 배운다는 데 초점이 있어요(외국에서 자란 아이가 그 나라 말을 익힘). 축적성은 문화가 세대를 이어 쌓여 간다는 데 초점이 있어요(조상의 지식에 후손이 새 지식을 더함).","keywords":["학습성","축적성"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#f2","kind":"faq","title":"자기 나라 문화를 자랑스러워하면 자문화 중심주의예요?","text":"자기 문화를 아끼고 자랑스러워하는 것은 자연스럽고 좋은 일이에요. 문제는 그 마음이 지나쳐 다른 문화를 낮게 보거나 무시할 때예요. 그때 자문화 중심주의가 돼요.","keywords":["문화","자문화 중심주의"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#m0","kind":"mistake","title":"자주 하는 실수","text":"본능이나 개인의 버릇도 문화라고 생각하는 실수 — 문화는 사회 구성원이 함께 가지고 배워서 익힌 것이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#m1","kind":"mistake","title":"자주 하는 실수","text":"자문화 중심주의와 문화 사대주의를 거꾸로 기억하는 실수 — 자문화 중심주의는 \"자기 문화가 최고\", 문화 사대주의는 \"남의 문화가 최고\"예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-08#m2","kind":"mistake","title":"자주 하는 실수","text":"문화 상대주의를 \"모든 관습을 무조건 인정하는 것\"으로 아는 실수 — 보편 윤리에 어긋나는 관습은 인정하지 않아요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-08","grade":"m1"},
{"id":"soc-m-1-09","kind":"unit","title":"민주주의와 시민","text":"정치와 민주주의의 의미, 민주주의의 발전 과정과 이념·원리, 현대 민주주의의 과제를 알아봐요. 정치의 의미를 좁은 의미와 넓은 의미로 나누어 설명하고, 공동체에서 정치가 하는 역할을 말할 수 있어요. 고대 아테네에서 시민 혁명, 참정권 확대에 이르는 민주주의의 발전 과정을 설명할 수 있어요. 민주주의의 이념(인간의 존엄성·자유·평등)과 기본 원리(국민 주…","keywords":["정치","민주주의","시민 혁명","천부 인권 사상","참정권","국민 주권","입헌주의","권력 분립","대의제"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c0","kind":"concept","title":"정치의 의미와 역할","text":"사람들은 함께 모여 살기 때문에 생각과 이익이 서로 부딪치는 일이 생겨요. 이런 갈등을 조정하고 해결하는 활동이 정치예요. 정치는 보는 범위에 따라 두 가지로 나누어 말해요. 구분 · 뜻 · 예 좁은 의미의 정치 · 국가가 하는 활동. 정치권력을 얻고, 유지하고, 행사하는 활동 · 국회","keywords":["정치"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c1","kind":"concept","title":"민주주의의 의미와 필요성","text":"민주주의는 국민이 나라의 주인이 되어 나라의 중요한 일을 스스로 결정하는 정치 방식이에요. 민주주의(democracy)라는 말은 고대 그리스어에서 민중을 뜻하는 말(demos)과 지배를 뜻하는 말(kratia)이 합쳐진 것으로, \"민중의 지배\"라는 뜻이에요. 민주주의가 필요한 까닭은 이","keywords":["정치","민주주의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c2","kind":"concept","title":"민주주의의 발전 과정","text":"민주주의는 오랜 시간에 걸쳐 조금씩 넓어지고 발전해 왔어요. 1. 고대 아테네의 민주 정치 기원전 5세기 무렵 그리스의 도시 국가 아테네에서는 시민들이 민회에 모여 나라의 중요한 일을 직접 토론하고 결정했어요(직접 민주 정치). 공직자도 대부분 추첨으로 뽑았어요. 하지만 성인 남자 시민","keywords":["정치","민주주의","시민 혁명","천부 인권 사상"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c3","kind":"concept","title":"민주주의의 이념 — 인간의 존엄성·자유·평등","text":"이념은 민주주의가 이루려고 하는 가장 중요한 가치예요. 인간의 존엄성: 모든 사람은 그 자체로 귀하고 소중한 존재라는 것이에요. 민주주의가 추구하는 가장 근본적인 이념이에요. 사람을 다른 목적을 위한 수단이나 물건처럼 대해서는 안 돼요. 자유: 다른 사람이나 국가로부터 부당하게 간섭받지","keywords":["민주주의"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c4","kind":"concept","title":"민주주의의 기본 원리","text":"민주주의의 이념을 실제로 이루려면 나라를 운영하는 원칙이 필요해요. 이것을 민주주의의 기본 원리라고 해요. 원리 · 뜻 · 예 국민 주권 · 나라의 주인으로서 나라의 일을 최종적으로 결정하는 힘(주권)이 국민에게 있다. · 헌법 제1조 제2항 \"대한민국의 주권은 국민에게 있고, 모든 권","keywords":["민주주의","국민 주권","입헌주의","권력 분립"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#c5","kind":"concept","title":"현대 민주주의 — 대의제와 시민의 역할","text":"오늘날 나라는 땅이 넓고 사람이 많아 아테네처럼 모든 국민이 한자리에 모이기 어려워요. 그래서 국민이 대표를 뽑고, 대표가 국민을 대신해 나라의 일을 결정하는 대의제(간접 민주 정치)를 운영해요. 대의제의 의의: 인구가 많은 나라에서도 민주 정치를 할 수 있고, 전문성을 갖춘 대표가 차","keywords":["정치","민주주의","대의제"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t0","kind":"term","title":"정치","text":"사회 구성원 사이의 의견 차이와 이해관계의 대립을 조정·해결해 공동의 목표를 이루는 활동이에요. 좁게는 국가가 정치권력을 얻고 행사하는 활동을 말해요.","keywords":["정치"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t1","kind":"term","title":"민주주의","text":"국민이 나라의 주인이 되어 나라의 중요한 일을 스스로 결정하는 정치 방식이에요. \"민중의 지배\"라는 뜻의 그리스어에서 나왔어요.","keywords":["민주주의"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t2","kind":"term","title":"시민 혁명","text":"17~18세기에 시민들이 왕의 절대 권력에 맞서 자유와 권리를 얻으려고 일으킨 혁명이에요. 예: 영국 명예혁명, 미국 독립 혁명, 프랑스 혁명","keywords":["시민 혁명"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t3","kind":"term","title":"천부 인권 사상","text":"사람은 태어날 때부터 하늘이 준 자유롭고 평등한 권리를 가진다는 생각이에요. 시민 혁명의 바탕이 되었어요.","keywords":["천부 인권 사상"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t4","kind":"term","title":"참정권","text":"국민이 나라의 정치에 참여할 수 있는 권리예요. 선거권, 선거에 나갈 수 있는 권리, 국민 투표권 등이 있어요.","keywords":["참정권"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t5","kind":"term","title":"국민 주권","text":"나라의 일을 최종적으로 결정하는 힘(주권)이 국민에게 있다는 원리예요.","keywords":["국민 주권"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t6","kind":"term","title":"입헌주의","text":"국가 권력을 헌법에 따라 행사해야 한다는 원리예요. 헌법으로 권력을 묶어 국민의 권리를 지켜요.","keywords":["입헌주의"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t7","kind":"term","title":"권력 분립","text":"국가 권력을 입법·행정·사법으로 나누어 서로 견제하고 균형을 이루게 하는 원리예요.","keywords":["권력 분립"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#t8","kind":"term","title":"대의제","text":"국민이 뽑은 대표가 국민을 대신해 나라의 일을 결정하는 제도예요. 간접 민주 정치라고도 해요.","keywords":["대의제"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#f0","kind":"faq","title":"좁은 의미의 정치랑 넓은 의미의 정치가 헷갈려요.","text":"누가 하는지를 먼저 보세요. 국회·정부·대통령처럼 국가가 정치권력을 얻고 쓰는 활동이면 좁은 의미의 정치예요. 학급 회의·주민 회의처럼 일상에서 의견 차이를 조정하는 활동까지 모두 넣으면 넓은 의미의 정치예요. 좁은 의미의 정치도 넓은 의미의 정치 안에 들어간다는 점을 기억하세요.","keywords":["정치"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#f1","kind":"faq","title":"이념이랑 기본 원리는 뭐가 달라요?","text":"이념은 민주주의가 이루려는 목표(가치)예요: 인간의 존엄성·자유·평등. 기본 원리는 그 목표를 이루려고 나라를 운영하는 원칙이에요: 국민 주권·국민 자치·입헌주의·권력 분립. \"무엇을 위해?\"에 대한 답이 이념, \"어떻게?\"에 대한 답이 원리라고 생각하면 쉬워요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#f2","kind":"faq","title":"아테네가 민주주의의 시작이라면서 왜 한계가 있다고 해요?","text":"아테네는 시민이 직접 나라 일을 결정했다는 점에서 민주주의의 뿌리예요. 하지만 그 \"시민\"은 성인 남자뿐이었고, 여성·노예·외국인은 참여할 수 없었어요. 모든 사람이 주인이 되는 오늘날 민주주의와 견주면 참여하는 사람의 범위가 좁았다는 한계가 있어요.","keywords":["민주주의"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#m0","kind":"mistake","title":"자주 하는 실수","text":"이념과 원리를 섞는 실수 — 인간의 존엄성·자유·평등은 이념, 국민 주권·국민 자치·입헌주의·권력 분립은 기본 원리예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#m1","kind":"mistake","title":"자주 하는 실수","text":"국민 주권과 국민 자치를 헷갈리는 실수 — 국민 주권은 \"주권이 누구에게 있나\"(국민), 국민 자치는 \"누가 다스리나\"(국민이 스스로 또는 대표를 통해)예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-09#m2","kind":"mistake","title":"자주 하는 실수","text":"시민 혁명 직후 모든 사람이 선거권을 가졌다고 생각하는 실수 — 처음에는 재산 있는 남성만 가졌고, 보통 선거는 참정권 확대 운동을 거쳐 20세기에 자리 잡았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-09","grade":"m1"},
{"id":"soc-m-1-10","kind":"unit","title":"정치 과정과 시민 참여","text":"선거와 정치 과정, 여러 정치 주체의 역할을 알고 지방 자치와 시민 참여의 중요성을 배워요. 선거의 기능과 민주 선거의 기본 원칙을 설명하고, 원칙에 어긋난 사례를 찾을 수 있어요. 선거 과정에서 유권자와 정당이 하는 활동을 말할 수 있어요. 정치 과정의 흐름과 정당·이익 집단·시민 단체·언론의 역할을 구별할 수 있어요. 지방 자치의 의미와 중요성을 알고…","keywords":["선거","유권자","공약","정치 과정","정당","이익 집단","시민 단체","지방 자치","조례","주민 참여 예산제"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c0","kind":"concept","title":"선거의 의미와 기능","text":"선거는 국민이 투표로 자신을 대신해 일할 대표를 뽑는 일이에요. 대의제 민주주의에서 국민이 주권을 행사하는 가장 대표적인 방법이에요. 선거는 이런 기능을 해요. 대표자 선출: 국민을 대신해 나라와 지역의 일을 맡을 대표를 뽑아요. 정치권력에 정당성 부여: 국민이 뽑았기 때문에 대표가 가","keywords":["선거","정당"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c1","kind":"concept","title":"민주 선거의 기본 원칙","text":"선거가 국민의 뜻을 공정하게 담으려면 네 가지 원칙을 지켜야 해요. 원칙 · 뜻 · 반대되는 모습 보통 선거 · 일정한 나이가 되면 누구나 선거권을 가져요. · 재산·성별·인종·학력에 따라 선거권을 주지 않는 제한 선거 평등 선거 · 누구나 한 사람이 한 표씩, 표의 가치가 같아요. ·","keywords":["선거"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c2","kind":"concept","title":"선거 과정 — 유권자와 정당의 활동","text":"선거권을 가진 사람을 유권자라고 해요. 우리나라는 만 18세 이상의 국민이 선거권을 가져요. 선거는 보통 후보자 등록 → 선거 운동 → 투표 → 개표 → 당선인 결정 순서로 진행되고, 선거 관리 위원회가 이 과정을 공정하게 관리해요. 정당이 하는 활동 선거에 나갈 후보자를 추천해요(공천","keywords":["선거","유권자","공약","정당"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c3","kind":"concept","title":"정치 과정과 정치 주체","text":"정치 과정은 사회의 여러 요구가 정책을 결정하는 기관(국회·정부)에 전달되어 정책으로 결정되고 집행되는 과정이에요. 요구·지지 투입 → 국회·정부의 정책 결정 → 법·정책으로 산출 → 그 결과에 대한 반응이 다시 투입되는 환류(피드백) 정치 과정에 참여해 영향을 주는 개인과 집단을 정치","keywords":["정치 과정","정당","이익 집단","시민 단체"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c4","kind":"concept","title":"지방 자치와 풀뿌리 민주주의","text":"지방 자치는 지역 주민이 그 지역의 일을 스스로, 또는 주민이 뽑은 대표를 통해 처리하는 제도예요. 이를 맡는 단체를 지방 자치 단체라고 해요(특별시·광역시·도 같은 광역 자치 단체, 시·군·자치구 같은 기초 자치 단체). 기관 · 하는 일 · 대표 지방 의회 · 조례(그 지역에서 지키","keywords":["선거","지방 자치","조례"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#c5","kind":"concept","title":"지역 문제 해결을 위한 시민 참여","text":"지역 문제(통학로 안전, 쓰레기 처리, 공원·도서관 부족 등)는 주민이 적극적으로 참여할 때 더 잘 해결돼요. 참여 방법 제도를 통한 참여: 주민 투표(지역의 중요한 일을 주민이 직접 결정), 주민 소환(단체장·지방 의원을 투표로 그만두게 함), 주민 조례 발안(조례를 만들거나 고치거나","keywords":["시민 단체","지방 자치","조례","주민 참여 예산제"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t0","kind":"term","title":"선거","text":"국민이 투표로 자신을 대신해 일할 대표를 뽑는 일이에요. 국민이 주권을 행사하는 대표적인 방법이에요.","keywords":["선거"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t1","kind":"term","title":"유권자","text":"선거권을 가진 사람이에요. 우리나라는 만 18세 이상의 국민이 선거권을 가져요.","keywords":["유권자"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t2","kind":"term","title":"공약","text":"후보자나 정당이 당선되면 실천하겠다고 유권자에게 하는 약속이에요.","keywords":["공약"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t3","kind":"term","title":"정치 과정","text":"사회의 여러 요구가 국회·정부에 전달되어 정책으로 결정되고 집행되는 과정이에요. 투입 → 정책 결정 → 산출 → 환류로 이어져요.","keywords":["정치 과정"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t4","kind":"term","title":"정당","text":"정치적 생각이 같은 사람들이 정권을 얻으려고 모인 단체예요. 후보자를 추천하고 정책을 내놓으며, 정치적 책임을 져요.","keywords":["정당"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t5","kind":"term","title":"이익 집단","text":"같은 이익을 가진 사람들이 자기 집단의 특수한 이익을 이루려고 만든 단체예요. 예: 노동조합, 직업별 단체","keywords":["이익 집단"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t6","kind":"term","title":"시민 단체","text":"시민들이 공익을 위해 자발적으로 만든 단체예요. 정부를 감시하고 환경·인권 같은 사회 문제를 해결하려고 활동해요.","keywords":["시민 단체"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t7","kind":"term","title":"지방 자치","text":"지역 주민이 그 지역의 일을 스스로, 또는 주민이 뽑은 대표를 통해 처리하는 제도예요. 풀뿌리 민주주의라고도 해요.","keywords":["지방 자치"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t8","kind":"term","title":"조례","text":"지방 의회가 법령의 범위 안에서 만드는, 그 지역에서 지키는 규칙이에요.","keywords":["조례"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#t9","kind":"term","title":"주민 참여 예산제","text":"지방 자치 단체가 예산을 짜는 과정에 주민이 직접 참여해 사업을 제안하고 의견을 내는 제도예요.","keywords":["주민 참여 예산제"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#f0","kind":"faq","title":"보통 선거랑 평등 선거가 아직도 헷갈려요.","text":"보통 선거는 \"선거권을 누가 갖나?\"의 문제예요. 재산·성별 때문에 선거권을 못 받으면 보통 선거 위반이에요. 평등 선거는 \"선거권을 가진 사람들의 표가 같은 무게인가?\"의 문제예요. 어떤 사람만 두 표를 받거나, 선거구 인구 차이로 한 표의 무게가 달라지면 평등 선거 문제예요.","keywords":["선거"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#f1","kind":"faq","title":"이익 집단은 자기 이익만 챙기니까 나쁜 거 아니에요?","text":"꼭 그렇지는 않아요. 이익 집단은 정당이 미처 챙기지 못한 특정 직업·집단의 목소리를 정치 과정에 전달하는 역할을 해요. 다만 지나치게 자기 이익만 내세우면 사회 전체의 이익을 해칠 수 있어서, 시민 단체·언론의 감시와 여러 집단 사이의 대화가 필요해요.","keywords":["이익 집단"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#f2","kind":"faq","title":"중학생도 지역 문제에 참여할 수 있어요?","text":"네. 선거권은 아직 없어도 지방 자치 단체 누리집에 의견 내기, 학생 의견 제안, 캠페인 참여, 청소년 의회 같은 활동으로 참여할 수 있어요. 일부 지역은 주민 참여 예산에 청소년이 제안할 수 있게 하기도 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#m0","kind":"mistake","title":"자주 하는 실수","text":"대리 투표를 비밀 선거 위반으로 생각하는 실수 — 남이 대신 투표하면 직접 선거, 투표 내용을 드러내면 비밀 선거에 어긋나요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#m1","kind":"mistake","title":"자주 하는 실수","text":"시민 단체와 이익 집단을 헷갈리는 실수 — 공익(모두의 이익)이면 시민 단체, 자기 집단의 특수한 이익이면 이익 집단이에요. 둘 다 정권을 얻으려 하지 않아요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-10#m2","kind":"mistake","title":"자주 하는 실수","text":"지방 의회와 지방 자치 단체장을 바꿔 생각하는 실수 — 조례를 만드는 곳은 지방 의회, 조례에 따라 집행하는 쪽은 단체장이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-10","grade":"m1"},
{"id":"soc-m-1-11","kind":"unit","title":"일상생활과 법","text":"법의 의미와 목적, 생활 속 여러 법의 종류를 알고 재판의 종류와 공정한 재판의 중요성을 배워요. 법의 의미와 특징(강제성)을 알고, 법과 도덕을 비교할 수 있어요. 법의 목적이 정의 실현임을 설명할 수 있어요. 공법·사법·사회법을 구별하고, 사회법이 등장한 배경을 말할 수 있어요. 민사 재판과 형사 재판을 구별하고, 공정한 재판을 위한 제도를 설명할 수…","keywords":["사회 규범","강제성","정의","공법","사법","사회법","민사 재판","형사 재판","심급 제도","사법권의 독립"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c0","kind":"concept","title":"법의 의미와 특징 — 법과 도덕","text":"사람들이 함께 살아가려면 지켜야 할 규칙이 필요해요. 이런 규칙을 사회 규범이라고 하고, 관습·도덕·종교 규범·법 등이 있어요. 법은 국가가 만들고, 지키지 않으면 국가가 처벌하거나 손해를 물어 주게 하는 등 강제로 따르게 하는 사회 규범이에요. 이렇게 국가의 힘으로 지키게 하는 성질을","keywords":["사회 규범","강제성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c1","kind":"concept","title":"법의 목적 — 정의 실현","text":"법이 이루려는 가장 중요한 목적은 정의를 실현하는 것이에요. 정의는 흔히 \"각자에게 그의 몫을 주는 것\"이라고 말해요. 고대 로마 때부터 이어져 온 생각이에요. 같은 경우는 같게, 다른 경우는 다르게 대해요. 누구든 같은 잘못을 하면 같은 기준으로 판단받아요. 일한 만큼 정당한 대가를 ","keywords":["정의"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c2","kind":"concept","title":"생활 속 법의 종류 — 공법과 사법","text":"법은 어떤 관계를 다루는지에 따라 나눌 수 있어요. 종류 · 다루는 관계 · 대표적인 법 공법 · 개인과 국가 사이, 국가 기관 사이의 관계 · 헌법(나라의 최고법, 국가 조직과 국민의 기본권), 형법(범죄와 형벌), 행정법(행정 기관의 일), 소송법(재판의 절차) 사법 · 개인과 개인","keywords":["공법","사법"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c3","kind":"concept","title":"사회법의 등장 배경과 필요성","text":"근대 사회에서는 개인끼리의 관계에 국가가 끼어들지 않는 것을 원칙으로 했어요. 예를 들어 계약은 당사자끼리 자유롭게 맺도록 했지요(계약 자유의 원칙). 그런데 자본주의가 발달하면서 문제가 생겼어요. 일자리가 급한 노동자는 회사가 내민 낮은 임금과 긴 노동 시간을 그대로 받아들일 수밖에 ","keywords":["공법","사법","사회법"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c4","kind":"concept","title":"재판의 의미와 종류 — 민사 재판과 형사 재판","text":"재판은 다툼이 생기거나 범죄가 일어났을 때 법원이 법을 적용해 옳고 그름을 판단하는 일이에요. 구분 · 민사 재판 · 형사 재판 언제 · 개인 사이에 돈·재산·계약·가족 관계 등으로 다툼이 생겼을 때 · 범죄가 일어나 범죄를 저질렀는지와 형벌을 정할 때 재판을 청구하는 사람 · 소송을 ","keywords":["민사 재판","형사 재판"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#c5","kind":"concept","title":"공정한 재판을 위한 제도","text":"재판은 사람의 재산·자유, 때로는 삶 전체를 좌우해요. 그래서 재판이 공정하게 이루어지도록 여러 제도를 두어요. 사법권의 독립: 법원은 국회나 정부 같은 다른 기관의 간섭을 받지 않아야 해요. 법관은 오직 헌법과 법률, 그리고 양심에 따라 독립하여 재판해요. 심급 제도: 한 사건에 대해","keywords":["사법","심급 제도","사법권의 독립"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t0","kind":"term","title":"사회 규범","text":"사회 구성원이 함께 살아가려고 지키기로 한 행동 기준이에요. 관습, 도덕, 종교 규범, 법 등이 있어요.","keywords":["사회 규범"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t1","kind":"term","title":"강제성","text":"법을 어기면 국가가 형벌이나 손해 배상 같은 제재를 하는 성질이에요. 법이 다른 사회 규범과 다른 가장 큰 특징이에요.","keywords":["강제성"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t2","kind":"term","title":"정의","text":"각자에게 그의 정당한 몫을 주는 것이에요. 법이 이루려는 가장 중요한 목적이에요.","keywords":["정의"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t3","kind":"term","title":"공법","text":"개인과 국가 사이, 국가 기관 사이의 관계를 다루는 법이에요. 예: 헌법, 형법, 행정법, 소송법","keywords":["공법"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t4","kind":"term","title":"사법","text":"개인과 개인 사이의 관계를 다루는 법이에요. 예: 민법, 상법","keywords":["사법"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t5","kind":"term","title":"사회법","text":"사회적 약자를 보호하려고 국가가 개인 사이의 관계에 개입하는 법이에요. 예: 노동법, 사회 보장법, 경제법","keywords":["사회법"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t6","kind":"term","title":"민사 재판","text":"개인 사이의 재산·계약·가족 관계 등의 다툼을 해결하는 재판이에요. 소송을 낸 사람은 원고, 당한 사람은 피고예요.","keywords":["민사 재판"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t7","kind":"term","title":"형사 재판","text":"범죄를 저질렀는지와 어떤 형벌을 줄지 정하는 재판이에요. 검사가 기소하고, 재판을 받는 사람은 피고인이에요.","keywords":["형사 재판"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t8","kind":"term","title":"심급 제도","text":"한 사건에 대해 급이 다른 법원에서 여러 번 재판받을 수 있게 한 제도예요. 우리나라는 원칙적으로 3심제예요.","keywords":["심급 제도"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#t9","kind":"term","title":"사법권의 독립","text":"법원이 다른 기관의 간섭 없이, 법관이 헌법과 법률과 양심에 따라 재판하게 하는 원칙이에요.","keywords":["사법권의 독립"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#f0","kind":"faq","title":"피고랑 피고인은 같은 말 아니에요?","text":"달라요. 피고는 민사 재판에서 소송을 당한 사람이고, 피고인은 형사 재판에서 범죄 혐의로 검사에게 기소된 사람이에요. 민사 재판의 피고는 범죄자가 아니에요. 돈을 갚지 않았다는 등의 다툼에서 상대방일 뿐이에요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#f1","kind":"faq","title":"공법이랑 사법은 어떻게 구별해요?","text":"관계를 맺은 쪽을 보세요. 국가가 권력을 가진 쪽으로 등장하면(세금, 처벌, 행정 처분) 공법이고, 개인끼리 대등하게 맺은 관계(계약, 결혼, 상속)면 사법이에요. 국가가 개인 사이의 관계에 끼어들어 약자를 보호하면 사회법이에요.","keywords":["공법","사법"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#f2","kind":"faq","title":"왜 재판을 세 번이나 받을 수 있어요? 시간 낭비 아니에요?","text":"법관도 사람이라 실수할 수 있어요. 잘못된 판결 하나가 한 사람의 재산이나 자유를 빼앗을 수 있기 때문에, 상급 법원에서 다시 따져 볼 기회를 주는 거예요. 시간은 더 걸리지만, 억울한 사람이 생기지 않게 하는 것이 더 중요하다고 보는 거예요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#m0","kind":"mistake","title":"자주 하는 실수","text":"피고와 피고인을 섞어 쓰는 실수 — 민사 재판은 원고·피고, 형사 재판은 검사·피고인이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#m1","kind":"mistake","title":"자주 하는 실수","text":"형사 재판을 피해자가 청구한다고 생각하는 실수 — 형사 재판은 검사가 기소해서 시작해요. 피해자가 손해를 물어 달라고 하는 것은 민사 재판이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-11#m2","kind":"mistake","title":"자주 하는 실수","text":"항소와 상고를 바꿔 쓰는 실수 — 1심 → 2심은 항소, 2심 → 3심은 상고예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-11","grade":"m1"},
{"id":"soc-m-1-12","kind":"unit","title":"인권과 기본권","text":"인권과 헌법이 보장하는 기본권, 기본권의 제한과 구제 방법, 근로자의 권리를 알아봐요. 인권의 의미와 특징을 말하고, 일상 속 인권 침해 사례를 찾을 수 있어요. 헌법이 보장하는 기본권(자유권·평등권·참정권·사회권·청구권)을 사례에 맞게 구별할 수 있어요. 헌법 제37조 제2항을 바탕으로 기본권 제한의 요건과 한계를 설명할 수 있어요. 기본권 침해와 근로…","keywords":["인권","기본권","자유권","평등권","참정권","사회권","청구권","헌법 소원 심판","국가 인권 위원회","근로 3권"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c0","kind":"concept","title":"인권의 의미와 특징","text":"인권은 사람이 사람답게 살기 위해 누구나 마땅히 누려야 하는 기본적인 권리예요. 인권에는 이런 특징이 있어요. 특징 · 뜻 천부 인권 · 국가나 누가 준 것이 아니라, 태어날 때부터 저절로 가지는 권리예요. 보편적 권리 · 인종·성별·나이·국적·장애 등과 관계없이 누구나 누려요. 불가침","keywords":["인권"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c1","kind":"concept","title":"헌법에 보장된 기본권 ① — 자유권과 평등권","text":"인권 가운데 헌법이 보장하는 권리를 기본권이라고 해요. 모든 기본권의 바탕에는 헌법 제10조의 인간의 존엄과 가치, 행복 추구권이 있어요. 모든 국민은 인간으로서의 존엄과 가치를 가지며, 행복을 추구할 권리를 가진다. (헌법 제10조) 자유권은 국가나 다른 사람으로부터 부당한 간섭을 받","keywords":["인권","기본권","자유권","평등권"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c2","kind":"concept","title":"헌법에 보장된 기본권 ② — 참정권·사회권·청구권","text":"참정권은 국민이 나라의 정치에 참여할 수 있는 권리예요. 국민 주권을 실현하는 능동적 권리예요. 예: 선거권, 공무 담임권(선거에 나가거나 공무원이 될 수 있는 권리), 국민 투표권 사회권은 국민이 인간다운 생활을 할 수 있도록 국가에 적극적으로 요구할 수 있는 권리예요. 자본주의 발달","keywords":["기본권","참정권","사회권","청구권"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c3","kind":"concept","title":"기본권 제한의 요건과 한계","text":"기본권은 소중하지만, 다른 사람의 권리나 공동체의 이익과 부딪칠 때가 있어요. 그래서 헌법은 기본권을 제한할 수 있는 조건과 넘을 수 없는 한계를 함께 정해 두었어요. 국민의 모든 자유와 권리는 국가안전보장·질서유지 또는 공공복리를 위하여 필요한 경우에 한하여 법률로써 제한할 수 있으며","keywords":["기본권"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c4","kind":"concept","title":"기본권 침해의 구제 방법","text":"기본권이 침해되었을 때 이를 바로잡는 방법을 구제 방법이라고 해요. 구제 방법 · 어디에 · 언제 국가 인권 위원회 진정 · 국가 인권 위원회 · 국가 기관 등의 인권 침해나, 회사·단체 등을 포함한 차별 행위가 있을 때. 조사한 뒤 바로잡도록 권고해요(강제로 따르게 하는 힘은 없어요)","keywords":["인권","기본권","헌법 소원 심판","국가 인권 위원회"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#c5","kind":"concept","title":"근로자의 권리와 권리 침해의 구제","text":"근로자는 회사(사용자)보다 약한 위치에 있기 쉬워요. 그래서 헌법은 근로의 권리와 함께 근로 3권을 보장해요. 근로 3권 · 뜻 단결권 · 근로자가 노동조합을 만들거나 가입할 수 있는 권리 단체 교섭권 · 노동조합이 임금·근로 시간 같은 근로 조건을 사용자와 교섭할 수 있는 권리 단체 ","keywords":["근로 3권"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t0","kind":"term","title":"인권","text":"사람이 사람답게 살기 위해 누구나 마땅히 누려야 하는 기본적인 권리예요. 천부 인권, 보편적·불가침·항구적 권리라는 특징이 있어요.","keywords":["인권"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t1","kind":"term","title":"기본권","text":"인권 가운데 헌법이 보장하는 권리예요. 자유권, 평등권, 참정권, 사회권, 청구권 등이 있어요.","keywords":["기본권"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t2","kind":"term","title":"자유권","text":"국가나 다른 사람으로부터 부당한 간섭을 받지 않을 권리예요. 예: 신체의 자유, 종교의 자유, 직업 선택의 자유","keywords":["자유권"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t3","kind":"term","title":"평등권","text":"성별·종교·사회적 신분 등을 까닭으로 부당하게 차별받지 않을 권리예요.","keywords":["평등권"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t4","kind":"term","title":"참정권","text":"국민이 나라의 정치에 참여할 수 있는 권리예요. 예: 선거권, 공무 담임권, 국민 투표권","keywords":["참정권"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t5","kind":"term","title":"사회권","text":"인간다운 생활을 위해 국가에 적극적으로 요구할 수 있는 권리예요. 예: 교육을 받을 권리, 근로의 권리, 환경권","keywords":["사회권"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t6","kind":"term","title":"청구권","text":"기본권이 침해되었을 때 국가에 구제를 청구할 수 있는 권리예요. 예: 청원권, 재판 청구권, 국가 배상 청구권","keywords":["청구권"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t7","kind":"term","title":"헌법 소원 심판","text":"공권력 때문에 기본권을 침해당한 사람이 헌법 재판소에 구제를 청구하는 제도예요.","keywords":["헌법 소원 심판"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t8","kind":"term","title":"국가 인권 위원회","text":"인권 침해와 차별 행위를 조사하고 바로잡도록 권고하는 국가 기관이에요.","keywords":["국가 인권 위원회"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#t9","kind":"term","title":"근로 3권","text":"헌법이 근로자에게 보장하는 단결권, 단체 교섭권, 단체 행동권이에요.","keywords":["근로 3권"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#f0","kind":"faq","title":"인권이랑 기본권은 같은 거예요?","text":"거의 겹치지만 같지는 않아요. 인권은 사람이라면 누구나 가지는 권리이고, 기본권은 그 인권 가운데 헌법이 보장하는 권리예요. 헌법에 적혀 있으니 국가가 지켜야 할 의무가 분명해지고, 침해되면 헌법 소원 같은 방법으로 구제받을 수 있어요.","keywords":["인권","기본권"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#f1","kind":"faq","title":"사회권이랑 청구권이 헷갈려요. 둘 다 국가에 요구하는 거잖아요?","text":"무엇을 요구하는지가 달라요. 사회권은 교육·일자리·생활 보장처럼 인간다운 생활 자체를 국가에 요구하는 권리예요. 청구권은 이미 침해된 기본권을 구제해 달라고 요구하는 권리예요(재판, 배상, 청원). 청구권은 다른 권리를 지키기 위한 \"수단\"이에요.","keywords":["사회권","청구권"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#f2","kind":"faq","title":"기본권은 소중하다면서 왜 제한할 수 있어요?","text":"내 권리가 다른 사람의 권리나 모두의 안전과 부딪칠 때가 있기 때문이에요. 예를 들어 표현의 자유가 있어도 남의 명예를 해치는 거짓말은 제한돼요. 다만 헌법은 제한하는 조건(목적·법률·필요한 만큼)과 넘을 수 없는 선(본질적 내용)을 정해, 국가가 기본권을 함부로 제한하지 못하게 막아 두었어요.","keywords":["기본권"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#m0","kind":"mistake","title":"자주 하는 실수","text":"사회권과 청구권을 헷갈리는 실수 — 교육·근로·인간다운 생활은 사회권, 재판·배상·청원은 청구권이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#m1","kind":"mistake","title":"자주 하는 실수","text":"기본권은 어떤 경우에도 제한할 수 없다고 생각하는 실수 — 목적·법률·필요한 만큼이라는 조건을 갖추면 제한할 수 있어요. 다만 본질적인 내용은 침해할 수 없어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-1-12#m2","kind":"mistake","title":"자주 하는 실수","text":"행정 심판과 행정 소송을 섞는 실수 — 행정 심판은 행정 기관(행정 심판 위원회)에, 행정 소송은 법원에 청구해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-1","unit":"soc-m-1-12","grade":"m1"},
{"id":"soc-m-2-01","kind":"unit","title":"헌법과 국가 기관","text":"우리나라의 정부 형태와 대통령·행정부, 국회, 법원, 헌법재판소가 하는 일을 알아봐요. 우리나라 정부 형태가 대통령제에 의원 내각제 요소를 더한 것임을 설명할 수 있어요. 대통령의 지위와 권한, 행정부의 구성을 말할 수 있어요. 국회의 구성과 법률이 만들어지는 과정, 국회의 권한을 설명할 수 있어요. 법원과 헌법재판소가 하는 일을 구별하고, 사법권 독립이…","keywords":["대통령제","의원 내각제","국가 원수","국무 회의","법률안 거부권","국정 감사","탄핵 소추","사법권의 독립","위헌 법률 심판","헌법 소원 심판"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c0","kind":"concept","title":"우리나라의 정부 형태","text":"정부 형태는 국가 권력, 특히 입법부(국회)와 행정부(정부)의 관계를 어떻게 짜 놓았는지를 말해요. 대표적인 정부 형태는 두 가지예요. 구분 · 대통령제 · 의원 내각제 행정부를 이끄는 사람 · 국민이 직접 뽑은 대통령 · 의회(국회)의 다수당이 구성한 내각과 총리 입법부와 행정부 · ","keywords":["대통령제","의원 내각제","법률안 거부권"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c1","kind":"concept","title":"대통령의 지위와 권한, 행정부의 구성","text":"행정은 법을 집행해 나라 살림을 꾸려 가는 일이에요. 행정을 맡은 국가 기관이 행정부(정부)예요. 대통령은 두 가지 지위를 가져요. 지위 · 뜻 · 권한의 예 국가 원수 · 나라 전체를 대표하는 사람 · 외국과 조약을 맺고 비준해요, 대법원장·헌법재판소장 등을 임명해요, 위기 때 긴급 ","keywords":["국가 원수","국무 회의","법률안 거부권"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c2","kind":"concept","title":"국회의 구성과 법률이 만들어지는 과정","text":"국회는 국민이 뽑은 대표들이 모인 국민의 대표 기관이자, 법률을 만드는 입법 기관이에요. 국회의원: 지역구에서 뽑힌 의원과, 정당이 얻은 표에 따라 나누는 비례 대표 의원이 있어요. 임기는 4년이에요. 헌법은 국회의원을 200명 이상으로 하도록 정하고 있어요. 국회의장과 부의장 2명이 ","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c3","kind":"concept","title":"국회의 권한","text":"국회는 크게 세 가지 권한을 가져요. 권한 · 내용 입법에 관한 권한 · 법률을 만들고 고쳐요. 헌법 개정안을 제안하고 의결해요. 중요한 조약을 맺고 비준하는 데 동의해요 재정에 관한 권한 · 정부가 낸 예산안을 심의·확정해요. 정부가 돈을 바르게 썼는지 결산을 심사해요. 세금의 종류와","keywords":["국정 감사","탄핵 소추"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c4","kind":"concept","title":"법원의 조직과 역할, 사법권의 독립","text":"사법은 법을 적용해 다툼을 해결하고 옳고 그름을 판단하는 일이에요. 사법권은 법원이 가져요. 법원의 조직 대법원: 최고 법원이에요. 대법원장과 대법관으로 이루어지고, 3심 사건을 맡아 최종 판단을 내려요. 고등 법원: 주로 2심 재판을 맡아요. 지방 법원: 주로 1심 재판을 맡아요. 특","keywords":["사법권의 독립"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#c5","kind":"concept","title":"헌법재판소의 성격과 하는 일","text":"헌법재판소는 헌법에 관한 다툼을 심판해 헌법을 지키고 국민의 기본권을 보장하는 기관이에요. 재판관 9명으로 이루어지는데, 대통령이 임명하되 3명은 국회가 선출하고 3명은 대법원장이 지명한 사람을 임명해요. 심판 · 언제 하나 위헌 법률 심판 · 재판 중에 적용될 법률이 헌법에 어긋나는지","keywords":["탄핵 소추","위헌 법률 심판","헌법 소원 심판"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t0","kind":"term","title":"대통령제","text":"국민이 직접 뽑은 대통령이 행정부를 이끌고, 입법부와 행정부가 엄격히 나뉘어 서로 견제하는 정부 형태예요.","keywords":["대통령제"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t1","kind":"term","title":"의원 내각제","text":"의회의 다수당이 내각을 구성해 행정부를 이끌고, 의회와 내각이 긴밀히 협조하는 정부 형태예요. 내각 불신임권과 의회 해산권이 있어요.","keywords":["의원 내각제"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t2","kind":"term","title":"국가 원수","text":"나라 전체를 대표하는 사람이에요. 우리나라 대통령은 국가 원수이면서 행정부 수반이에요.","keywords":["국가 원수"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t3","kind":"term","title":"국무 회의","text":"정부의 중요한 정책을 심의하는 회의예요. 대통령이 의장, 국무총리가 부의장이에요.","keywords":["국무 회의"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t4","kind":"term","title":"법률안 거부권","text":"국회에서 통과된 법률안에 이의가 있을 때 대통령이 국회에 다시 의결해 달라고 돌려보내는 권한이에요.","keywords":["법률안 거부권"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t5","kind":"term","title":"국정 감사","text":"국회가 해마다 정해진 기간에 국정 전반을 살펴보는 일이에요. 특정 사안만 조사하는 것은 국정 조사예요.","keywords":["국정 감사"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t6","kind":"term","title":"탄핵 소추","text":"대통령·국무총리·법관 같은 고위 공무원이 직무에서 헌법이나 법률을 어겼을 때, 국회가 파면을 요구하며 헌법재판소에 심판을 청구하는 일이에요.","keywords":["탄핵 소추"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t7","kind":"term","title":"사법권의 독립","text":"법원이 국회·정부의 간섭을 받지 않고, 법관이 헌법과 법률과 양심에 따라 재판하게 하는 원칙이에요.","keywords":["사법권의 독립"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t8","kind":"term","title":"위헌 법률 심판","text":"재판에 적용될 법률이 헌법에 어긋나는지를 법원의 제청으로 헌법재판소가 판단하는 심판이에요.","keywords":["위헌 법률 심판"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#t9","kind":"term","title":"헌법 소원 심판","text":"공권력 때문에 기본권을 침해받은 국민이 헌법재판소에 직접 구제를 청구하는 심판이에요.","keywords":["헌법 소원 심판"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#f0","kind":"faq","title":"대통령제인데 왜 국무총리가 있어요?","text":"국무총리는 원래 의원 내각제의 요소예요. 우리나라는 대통령제를 기본으로 하면서, 국무총리가 대통령을 보좌하고 행정 각부를 조정하게 했어요. 국무총리를 임명할 때 국회의 동의를 얻게 해서 국회와 정부가 협조하고 서로 견제하도록 했지요.","keywords":["대통령제"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#f1","kind":"faq","title":"법원과 헌법재판소는 뭐가 달라요?","text":"법원은 개인 사이의 다툼이나 범죄 같은 일반 사건을 재판해요. 헌법재판소는 법률이 헌법에 맞는지, 기본권이 침해되었는지, 탄핵·정당 해산·국가 기관 사이의 권한 다툼처럼 헌법에 관한 문제를 심판해요. 법원이 재판 중에 법률이 헌법에 어긋난다고 의심되면 헌법재판소에 심판을 제청하기도 해요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#f2","kind":"faq","title":"국정 감사랑 국정 조사는 어떻게 구별해요?","text":"국정 감사는 해마다 정해진 기간에 국정 전반을 살펴보는 것이고, 국정 조사는 특정한 사안이 생겼을 때 그 일을 조사하는 것이에요. \"해마다, 전체\"면 감사, \"필요할 때, 특정 사건\"이면 조사라고 기억해요.","keywords":["국정 감사"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#m0","kind":"mistake","title":"자주 하는 실수","text":"위헌 법률 심판과 헌법 소원 심판을 헷갈리는 실수 — 법원이 제청하면 위헌 법률 심판, 기본권을 침해받은 국민이 직접 청구하면 헌법 소원 심판이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#m1","kind":"mistake","title":"자주 하는 실수","text":"법률안 거부권을 국회의 권한으로 아는 실수 — 거부권은 대통령이 국회를 견제하는 권한이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-01#m2","kind":"mistake","title":"자주 하는 실수","text":"국무 회의가 정책을 \"의결\"한다고 아는 실수 — 국무 회의는 정부의 중요한 정책을 심의하는 기관이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-01","grade":"m2"},
{"id":"soc-m-2-02","kind":"unit","title":"경제생활과 선택","text":"기회비용과 편익을 따지는 합리적 선택, 자산과 신용 관리, 기업의 역할과 책임을 배워요. 자원의 희소성 때문에 선택이 필요하다는 것을 설명할 수 있어요. 기회비용과 편익을 비교해 합리적으로 선택할 수 있어요. 생애 주기에 따른 소득과 소비를 알고, 예금·주식·채권의 특징을 비교하며 신용을 관리하는 방법을 말할 수 있어요. 기업의 역할과 사회적 책임, 기업…","keywords":["희소성","편익","기회비용","합리적 선택","생애 주기","자산","유동성","채권","신용","기업가 정신"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c0","kind":"concept","title":"자원의 희소성과 선택","text":"사람의 욕구는 끝이 없지만, 그 욕구를 채워 줄 돈·시간·물건 같은 자원은 한정되어 있어요. 이렇게 사람들의 욕구에 비해 자원이 부족한 상태를 희소성이라고 해요. 희소성은 상대적인 개념이에요. 양이 많아도 원하는 사람이 더 많으면 희소하고, 양이 적어도 원하는 사람이 없으면 희소하지 않","keywords":["희소성"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c1","kind":"concept","title":"기회비용과 편익 — 합리적 선택","text":"무엇을 선택하면 다른 것은 포기해야 해요. 편익: 선택으로 얻는 만족이나 이익이에요. 기회비용: 선택 때문에 포기한 대안들 가운데 가치가 가장 큰 것이에요. 예를 들어 토요일 오후에 축구(만족 7), 영화(만족 9), 낮잠(만족 4) 중 하나만 할 수 있다고 해요. 영화를 고르면 포기한","keywords":["편익","기회비용","합리적 선택"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c2","kind":"concept","title":"생애 주기에 따른 소득과 소비","text":"생애 주기는 사람이 태어나서 죽을 때까지 거치는 단계(유소년기 → 청년기 → 중·장년기 → 노년기)예요. 단계마다 소득과 소비가 달라요. 소득: 일한 대가로 받는 임금처럼 경제 활동으로 얻는 돈이에요. 소비: 생활에 필요한 물건과 서비스를 사는 데 돈을 쓰는 것이에요. 시기 · 소득 ·","keywords":["생애 주기"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c3","kind":"concept","title":"자산 관리 — 안전성·수익성·유동성","text":"자산은 개인이 가진 경제적 가치가 있는 재산(현금, 예금, 주식, 채권, 부동산 등)이에요. 자산을 어디에 맡길지 고를 때는 세 가지를 따져요. 안전성: 원금(처음 맡긴 돈)을 잃지 않을 가능성 수익성: 이자나 가격 상승으로 돈을 불릴 수 있는 정도 유동성: 필요할 때 쉽게 현금으로 바","keywords":["자산","유동성","채권"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c4","kind":"concept","title":"신용과 신용 관리","text":"신용은 돈을 빌리거나 물건을 먼저 사고, 나중에 약속한 대로 갚을 수 있는 능력에 대한 믿음이에요. 신용 카드로 물건을 사거나 은행에서 대출을 받는 것은 모두 신용을 이용하는 거예요. 신용을 쓰면 당장 돈이 없어도 필요한 것을 살 수 있어 편리해요. 하지만 결국 미래의 소득으로 갚아야 ","keywords":["신용"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#c5","kind":"concept","title":"기업의 역할과 사회적 책임, 기업가 정신","text":"기업은 이윤을 얻으려고 재화와 서비스를 생산하는 경제 주체예요. 기업은 우리 경제에서 이런 역할을 해요. 생산: 사람들에게 필요한 재화와 서비스를 만들어 공급해요. 고용: 일자리를 만들어 사람들이 소득을 얻게 해요. 투자: 공장·기계를 늘리고 기술을 개발해 경제가 성장하게 해요. 세금을","keywords":["기업가 정신"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t0","kind":"term","title":"희소성","text":"사람들의 욕구에 비해 자원이 부족한 상태예요. 상대적인 개념이라 같은 물건도 때와 곳에 따라 희소성이 달라요.","keywords":["희소성"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t1","kind":"term","title":"편익","text":"어떤 선택으로 얻는 만족이나 이익이에요.","keywords":["편익"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t2","kind":"term","title":"기회비용","text":"어떤 것을 선택해서 포기한 대안들 가운데 가치가 가장 큰 것이에요. 포기한 것을 모두 더하지 않아요.","keywords":["기회비용"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t3","kind":"term","title":"합리적 선택","text":"비용(기회비용)에 비해 편익이 가장 큰 것을 고르는 선택이에요.","keywords":["합리적 선택"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t4","kind":"term","title":"생애 주기","text":"사람이 태어나서 죽을 때까지 거치는 단계예요. 유소년기, 청년기, 중·장년기, 노년기로 나누어요.","keywords":["생애 주기"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t5","kind":"term","title":"자산","text":"개인이 가진 경제적 가치가 있는 재산이에요. 예: 현금, 예금, 주식, 채권, 부동산","keywords":["자산"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t6","kind":"term","title":"유동성","text":"자산을 필요할 때 쉽게 현금으로 바꿀 수 있는 정도예요.","keywords":["유동성"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t7","kind":"term","title":"채권","text":"정부·공공 기관·기업이 돈을 빌리면서 발행하는 증서예요. 정해진 이자를 받고 만기에 원금을 돌려받아요.","keywords":["채권"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t8","kind":"term","title":"신용","text":"돈을 빌리거나 물건을 먼저 사고 나중에 약속대로 갚을 수 있는 능력에 대한 믿음이에요.","keywords":["신용"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#t9","kind":"term","title":"기업가 정신","text":"위험을 무릅쓰고 새로운 상품·생산 방법·시장에 도전하는 혁신적인 자세예요.","keywords":["기업가 정신"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#f0","kind":"faq","title":"기회비용은 포기한 걸 다 더하는 거 아니에요?","text":"아니에요. 여러 대안 가운데 하나만 고를 수 있었다면, 포기한 것들을 한꺼번에 다 할 수는 없었어요. 그래서 포기한 것 중 가장 가치가 큰 것 하나만 기회비용이에요. 예를 들어 축구(7), 영화(9), 낮잠(4) 가운데 영화를 고르면 기회비용은 7+4=11이 아니라 7이에요.","keywords":["기회비용"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#f1","kind":"faq","title":"안전하면서 수익도 많고 언제든 찾을 수 있는 자산은 없어요?","text":"안타깝게도 세 가지를 모두 갖춘 자산은 없어요. 수익이 높을수록 대개 위험도 커요. 그래서 목적(언제 쓸 돈인지, 잃어도 괜찮은 돈인지)에 맞게 고르고, 여러 자산에 나누어 맡기는 분산 투자를 해요.","keywords":["자산"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#f2","kind":"faq","title":"기업은 돈을 버는 게 목적인데 왜 사회적 책임까지 져야 해요?","text":"기업은 사회 속에서 소비자·노동자·지역 주민과 함께 활동해요. 기업이 환경을 오염시키거나 소비자를 속이면 사회 전체가 피해를 입어요. 또 소비자의 믿음을 잃으면 결국 기업도 오래 살아남기 어려워요. 그래서 이윤을 추구하면서도 법을 지키고 사회에 대한 책임을 다해야 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#m0","kind":"mistake","title":"자주 하는 실수","text":"기회비용을 구할 때 포기한 대안의 가치를 모두 더하는 실수 — 포기한 것 중 가장 가치가 큰 것 하나만 기회비용이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#m1","kind":"mistake","title":"자주 하는 실수","text":"돈을 쓰지 않았으니 기회비용이 0이라고 생각하는 실수 — 시간을 써서 포기한 다른 일(예: 아르바이트 소득)도 기회비용이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-02#m2","kind":"mistake","title":"자주 하는 실수","text":"희소성을 \"양이 적은 것\"으로만 아는 실수 — 희소성은 욕구에 비해 부족한 정도라서 상대적이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-02","grade":"m2"},
{"id":"soc-m-2-03","kind":"unit","title":"시장과 가격","text":"시장의 의미와 수요·공급 법칙을 알고, 시장 가격이 정해지고 변하는 원리를 탐구해요. 시장의 의미와 종류를 알고, 분업과 교환 때문에 시장이 필요하다는 것을 설명할 수 있어요. 수요 법칙과 공급 법칙을 설명할 수 있어요. 초과 수요·초과 공급이 사라지며 균형 가격이 정해지는 과정을 설명할 수 있어요. 수요와 공급을 변화시키는 요인에 따라 가격이 어떻게 변…","keywords":["시장","분업","수요 법칙","공급 법칙","초과 수요","초과 공급","균형 가격","대체재","보완재"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c0","kind":"concept","title":"시장의 의미와 종류, 시장이 필요한 까닭","text":"시장은 상품을 사려는 사람(수요자)과 팔려는 사람(공급자)이 만나 거래가 이루어지는 곳이에요. 꼭 눈에 보이는 장소가 아니어도 돼요. 기준 · 종류 · 예 눈에 보이는가 · 눈에 보이는 시장 · 전통 시장, 대형 마트, 꽃 시장 · 눈에 보이지 않는 시장 · 인터넷 쇼핑, 주식 시장, ","keywords":["시장","분업"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c1","kind":"concept","title":"수요와 수요 법칙","text":"수요는 어떤 상품을 일정한 가격에 사려고 하는 욕구예요. 단순히 갖고 싶은 마음이 아니라, 살 수 있는 능력(돈)이 뒷받침된 욕구예요. 수요량은 어떤 가격에서 사람들이 사려고 하는 상품의 양이에요. 수요 법칙: 다른 조건이 같을 때, 상품의 가격이 오르면 수요량은 줄고, 가격이 내리면 ","keywords":["수요 법칙"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c2","kind":"concept","title":"공급과 공급 법칙","text":"공급은 어떤 상품을 일정한 가격에 팔려고 하는 욕구예요. 공급량은 어떤 가격에서 생산자가 팔려고 하는 상품의 양이에요. 공급 법칙: 다른 조건이 같을 때, 상품의 가격이 오르면 공급량은 늘고, 가격이 내리면 공급량은 줄어요. 가격과 공급량은 같은 방향으로 움직여요. 떡볶이 한 접시 가격","keywords":["수요 법칙","공급 법칙"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c3","kind":"concept","title":"시장 가격의 결정 — 균형 가격","text":"시장에서 수요자와 공급자가 만나면 가격이 정해져요. 가격(원) · 3,000 · 4,000 · 5,000 수요량(접시) · 120 · 90 · 60 공급량(접시) · 60 · 90 · 120 상태 · 초과 수요 60 · 균형 · 초과 공급 60 초과 수요: 가격이 낮아 수요량이 공급량보","keywords":["시장","초과 수요","초과 공급","균형 가격"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c4","kind":"concept","title":"수요와 공급의 변화, 그리고 가격 변동","text":"상품 자체의 가격이 아닌 다른 요인이 바뀌면, 같은 가격에서도 사려는 양이나 팔려는 양 전체가 달라져요. 이것을 수요의 변화, 공급의 변화라고 해요. 수요를 늘리는 요인(수요 증가) · 공급을 늘리는 요인(공급 증가) 소득 증가(대부분의 상품) · 원료값·임금 같은 생산 요소 가격 하락","keywords":["대체재","보완재"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#c5","kind":"concept","title":"가격 변동에 대한 소비자와 생산자의 대응","text":"시장 가격은 신호등과 같아요. 가격이 오르거나 내리면 소비자와 생산자는 그 신호를 보고 행동을 바꿔요. 소비자의 대응 값이 오른 상품을 덜 사고, 대체재를 찾아요(예: 돼지고기값이 오르면 닭고기를 사요). 꼭 필요한 양만 사고, 아껴 쓰거나 다시 써요. 여러 가게의 가격을 비교해 더 싸","keywords":["시장","대체재"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t0","kind":"term","title":"시장","text":"사려는 사람과 팔려는 사람이 만나 거래가 이루어지는 곳이에요. 인터넷 쇼핑처럼 눈에 보이지 않는 시장도 있어요.","keywords":["시장"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t1","kind":"term","title":"분업","text":"생산 과정을 여러 단계로 나누거나, 사람마다 잘하는 일을 나누어 맡는 것이에요. 분업으로 생산이 늘면 교환이 필요해져요.","keywords":["분업"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t2","kind":"term","title":"수요 법칙","text":"다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 느는 관계예요.","keywords":["수요 법칙"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t3","kind":"term","title":"공급 법칙","text":"다른 조건이 같을 때 가격이 오르면 공급량이 늘고, 가격이 내리면 공급량이 주는 관계예요.","keywords":["공급 법칙"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t4","kind":"term","title":"초과 수요","text":"어떤 가격에서 수요량이 공급량보다 많은 상태예요. 가격이 오르는 압력이 생겨요.","keywords":["초과 수요"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t5","kind":"term","title":"초과 공급","text":"어떤 가격에서 공급량이 수요량보다 많은 상태예요. 가격이 내리는 압력이 생겨요.","keywords":["초과 공급"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t6","kind":"term","title":"균형 가격","text":"수요량과 공급량이 같아지는 곳에서 정해지는 가격이에요. 시장 가격이라고도 해요.","keywords":["균형 가격"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t7","kind":"term","title":"대체재","text":"서로 대신해서 쓸 수 있는 상품이에요. 예: 커피와 녹차, 돼지고기와 닭고기","keywords":["대체재"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#t8","kind":"term","title":"보완재","text":"함께 쓸 때 만족이 커지는 상품이에요. 예: 빵과 버터","keywords":["보완재"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#f0","kind":"faq","title":"수요랑 수요량은 뭐가 달라요?","text":"수요는 상품을 사려는 욕구 전체(여러 가격에서 각각 얼마나 사려는지의 관계)이고, 수요량은 어떤 한 가격에서 사려는 양이에요. 그 상품의 가격이 변해 사려는 양이 바뀌면 \"수요량의 변화\", 소득·기호·다른 상품 가격처럼 다른 요인 때문에 바뀌면 \"수요의 변화\"라고 해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#f1","kind":"faq","title":"균형 가격은 누가 정해요?","text":"어느 한 사람이 정하지 않아요. 가격이 낮으면 사려는 사람끼리 경쟁해 값이 오르고, 가격이 높으면 팔려는 사람끼리 경쟁해 값이 내려요. 이렇게 오르내리다가 사려는 양과 팔려는 양이 같아지는 곳에서 저절로 정해져요.","keywords":["균형 가격"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#f2","kind":"faq","title":"대체재랑 보완재는 어떻게 구별해요?","text":"\"둘 중 하나만 있으면 되나?\"를 물어보세요. 하나만 있으면 되면(커피 또는 녹차) 대체재, 함께 있어야 더 좋으면(빵과 버터) 보완재예요. 대체재는 한쪽 값이 오르면 다른 쪽 수요가 늘고, 보완재는 한쪽 값이 오르면 다른 쪽 수요도 줄어요.","keywords":["대체재","보완재"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#m0","kind":"mistake","title":"자주 하는 실수","text":"초과 수요일 때 가격이 내린다고 생각하는 실수 — 사려는 사람이 더 많으면 경쟁 때문에 가격이 올라요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#m1","kind":"mistake","title":"자주 하는 실수","text":"그 상품 가격이 변한 것을 \"수요의 변화\"라고 하는 실수 — 자기 가격 때문이면 수요량의 변화예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-03#m2","kind":"mistake","title":"자주 하는 실수","text":"보완재 가격이 오르면 이 상품 수요가 는다고 생각하는 실수 — 함께 쓰는 상품이 비싸지면 이 상품도 덜 사요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-03","grade":"m2"},
{"id":"soc-m-2-04","kind":"unit","title":"우리나라 경제와 세계화","text":"국내 총생산, 물가와 실업, 환율이 무엇이고 우리 생활에 어떤 영향을 주는지 알아봐요. 국내 총생산(GDP)의 의미를 알고, GDP로 알 수 없는 것(한계)을 말할 수 있어요. 경제 성장이 우리 생활을 어떻게 바꾸었는지 설명할 수 있어요. 인플레이션과 실업이 생활에 주는 영향을 설명할 수 있어요. 환율의 의미를 알고, 환율이 오르내릴 때 누가 유리하고 불…","keywords":["국내 총생산(GDP)","1인당 GDP","중간재","경제 성장","물가","인플레이션","실업","마찰적 실업","환율","외환 시장"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c0","kind":"concept","title":"국내 총생산(GDP)의 의미와 한계","text":"국내 총생산(GDP)은 일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 더한 것이에요. 한 나라의 경제 규모와 생산 수준을 보여 주는 대표적인 지표예요. 핵심 말 · 뜻 · 그래서 한 나라 안에서 · 생산한 사람의 국적이 아니라 장소를 따져요 · 우리나라에 ","keywords":["국내 총생산(GDP)","1인당 GDP","중간재"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c1","kind":"concept","title":"경제 성장과 우리 생활의 변화","text":"경제 성장은 한 나라 경제의 생산 규모가 커지는 것이에요. 보통 물가 변동의 영향을 뺀 실질 GDP가 얼마나 늘었는지로 나타내요. 경제 성장률(%) = (올해 실질 GDP−작년 실질 GDP)/(작년 실질 GDP)×100 우리나라는 1960년대부터 공업화를 추진해 빠르게 성장했어요(6학년","keywords":["경제 성장","물가"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c2","kind":"concept","title":"물가와 인플레이션","text":"물가는 여러 상품의 가격을 종합해 평균한 수준이에요. 물가가 어떻게 변하는지는 물가 지수로 나타내요. 기준이 되는 해의 물가를 100으로 두고, 다른 해의 물가가 얼마인지 나타낸 것이에요. 물가 지수가 110이면 기준 해보다 물가가 10% 올랐다는 뜻이에요. 인플레이션은 물가가 지속적으","keywords":["물가","인플레이션"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c3","kind":"concept","title":"실업의 의미와 유형, 생활에 미치는 영향","text":"실업은 일할 능력과 의사가 있는데도 일자리를 얻지 못한 상태예요. 일할 생각이 없는 학생이나 스스로 쉬고 있는 사람은 실업자가 아니에요. 유형 · 언제 생기나 · 예 경기적 실업 · 경기가 나빠져 기업이 생산과 고용을 줄일 때 · 불황으로 회사가 직원을 줄였어요 구조적 실업 · 산업 구","keywords":["실업","마찰적 실업"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c4","kind":"concept","title":"국제 거래의 확대와 환율","text":"국제 거래는 나라와 나라 사이에 상품·서비스와 노동·자본·기술 같은 생산 요소를 사고파는 것이에요. 나라마다 자원·기술·노동력이 달라서, 각자 잘 만드는 것을 특화해 생산하고 서로 교환하면 모두 이익을 얻을 수 있어요. 교통·통신이 발달하고, 세계 무역 기구(WTO)와 자유 무역 협정(","keywords":["환율","외환 시장"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#c5","kind":"concept","title":"환율 변동이 우리 생활에 미치는 영향","text":"환율이 오르면(예: 1달러 = 1,000원 → 1,200원) 1달러를 얻는 데 원화가 더 많이 들어요. 곧 원화의 가치가 떨어진 것이에요. · 환율 상승(원화 가치 하락) · 환율 하락(원화 가치 상승) 수출 · 외국에서 우리 상품의 달러 값이 싸져 늘어요 · 달러 값이 비싸져 줄어요 ","keywords":["물가","환율"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t0","kind":"term","title":"국내 총생산(GDP)","text":"일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 더한 것이에요.","keywords":["국내 총생산(GDP)"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t1","kind":"term","title":"1인당 GDP","text":"GDP를 그 나라의 인구로 나눈 값이에요. 국민의 평균적인 생활 수준을 짐작하게 해 줘요.","keywords":["1인당 GDP"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t2","kind":"term","title":"중간재","text":"다른 상품을 만드는 데 쓰이는 물건이에요. 예: 빵을 만드는 밀가루. GDP를 셀 때 따로 더하지 않아요.","keywords":["중간재"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t3","kind":"term","title":"경제 성장","text":"한 나라 경제의 생산 규모가 커지는 것이에요. 보통 실질 GDP가 늘어난 비율(경제 성장률)로 나타내요.","keywords":["경제 성장"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t4","kind":"term","title":"물가","text":"여러 상품의 가격을 종합해 평균한 수준이에요. 물가 지수로 변화를 나타내요.","keywords":["물가"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t5","kind":"term","title":"인플레이션","text":"물가가 지속적으로 오르는 현상이에요. 화폐 가치가 떨어져요.","keywords":["인플레이션"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t6","kind":"term","title":"실업","text":"일할 능력과 의사가 있는데도 일자리를 얻지 못한 상태예요.","keywords":["실업"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t7","kind":"term","title":"마찰적 실업","text":"더 나은 일자리를 찾으려고 잠시 일을 쉬는 동안 생기는 실업이에요.","keywords":["마찰적 실업"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t8","kind":"term","title":"환율","text":"우리 돈과 외국 돈을 바꾸는 교환 비율이에요. 예: 1달러 = 1,200원","keywords":["환율"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#t9","kind":"term","title":"외환 시장","text":"외국 돈(외화)을 사고파는 시장이에요. 환율은 이곳에서 외화의 수요와 공급으로 정해져요.","keywords":["외환 시장"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#f0","kind":"faq","title":"환율이 오르면 좋은 거예요, 나쁜 거예요?","text":"누구냐에 따라 달라요. 환율이 오르면(원화 가치 하락) 수출 기업과 우리나라에 오는 외국인 관광객은 유리하지만, 원료를 수입하는 기업, 해외여행·유학을 가는 사람, 달러 빚을 갚아야 하는 기업은 불리해요. 그래서 환율이 지나치게 빠르게 오르내리지 않는 것이 중요해요.","keywords":["환율"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#f1","kind":"faq","title":"왜 중고품 거래는 GDP에 안 들어가요?","text":"중고품은 처음 만들어진 해에 이미 GDP에 들어갔어요. 다시 사고팔 때 또 넣으면 같은 물건을 두 번 세게 돼요. GDP는 그 기간에 새로 생산된 것만 세요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#f2","kind":"faq","title":"학생인 저는 일을 안 하는데 실업자예요?","text":"아니에요. 실업자는 일할 능력과 의사가 있는데도 일자리를 얻지 못한 사람이에요. 학생은 지금 일하려는 사람이 아니라서 실업자가 아니라 비경제 활동 인구에 들어가요.","keywords":["실업"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#m0","kind":"mistake","title":"자주 하는 실수","text":"\"환율 상승 = 원화 가치 상승\"으로 거꾸로 아는 실수 — 1달러에 더 많은 원화가 필요해지니 원화 가치는 떨어진 거예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#m1","kind":"mistake","title":"자주 하는 실수","text":"GDP를 구할 때 중간재 값까지 모두 더하는 실수 — 최종 생산물의 가치만 더해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-04#m2","kind":"mistake","title":"자주 하는 실수","text":"실업률을 15세 이상 인구 전체로 나누는 실수 — 경제 활동 인구(취업자 + 실업자)로 나누어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-04","grade":"m2"},
{"id":"soc-m-2-05","kind":"unit","title":"국제 사회와 한반도","text":"국제 사회의 특징과 행위 주체, 국제 분쟁, 우리나라가 마주한 국제 문제와 대응을 알아봐요. 국제 사회의 특징(주권 국가 중심, 힘의 논리와 국제법, 상호 의존)을 설명할 수 있어요. 국가·국제기구·다국적 기업·개인 등 국제 사회의 행위 주체를 구분하고 그 역할을 말할 수 있어요. 국제 분쟁의 원인을 사례에서 찾고, 평화를 위해 시민이 할 수 있는 일을 …","keywords":["국제 사회","주권 국가","국제법","정부 간 국제기구","국제 비정부 기구","다국적 기업","국제 분쟁","동북공정","외교","공공 외교"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#c0","kind":"concept","title":"국제 사회의 특징","text":"국제 사회는 여러 나라가 서로 관계를 맺으며 함께 살아가는 사회예요. 한 나라 안의 사회와 비교하면 다음과 같은 특징이 있어요. 주권 국가 중심: 국제 사회의 기본 단위는 주권을 가진 나라(주권 국가)예요. 나라들은 크기나 힘과 관계없이 형식적으로 평등해요. 중앙 정부가 없음: 한 나라","keywords":["국제 사회","주권 국가","국제법"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#c1","kind":"concept","title":"국제 사회의 행위 주체","text":"국제 사회에서 활동하며 영향을 주는 주체를 행위 주체라고 해요. 행위 주체 · 특징 · 예 국가 · 국제 사회의 가장 기본적인 행위 주체. 주권을 가지고 외교·조약 체결을 해요. · 정상 회담, 조약 맺기 정부 간 국제기구 · 여러 나라 정부가 회원이 되어 만든 기구 · 국제 연합(UN","keywords":["국제 사회","정부 간 국제기구","국제 비정부 기구","다국적 기업","외교"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#c2","kind":"concept","title":"국제 분쟁의 원인과 사례","text":"나라나 집단 사이의 다툼이 국경을 넘어 커진 것을 국제 분쟁이라고 해요. 국제 분쟁은 보통 한 가지가 아니라 여러 원인이 얽혀 일어나요. 원인 · 내용 · 사례 영토 · 땅·섬을 서로 자기 것이라고 주장 · 카슈미르 분쟁(인도·파키스탄), 쿠릴 열도(러시아·일본) 자원 · 석유·천연가스","keywords":["국제 분쟁"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#c3","kind":"concept","title":"우리나라가 마주한 국제 문제","text":"한반도는 중국·일본·러시아 같은 주변국과 가깝고, 남북이 분단되어 있어 여러 국제 문제를 마주하고 있어요. 안보 문제: 남북 분단으로 군사적 긴장이 이어지고, 북한의 핵·미사일 개발은 한반도와 동북아시아의 평화를 위협하는 문제예요. 일본과의 문제: 일본은 우리 영토인 독도에 대해 부당하","keywords":["동북공정"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#c4","kind":"concept","title":"국제 문제를 해결하기 위한 노력","text":"국제 문제는 한 나라의 힘만으로 해결하기 어려워요. 그래서 여러 주체가 함께 노력해요. 외교: 나라가 다른 나라와 관계를 맺고 대화·협상으로 자기 나라의 이익을 지키는 활동이에요. 정상 회담, 조약 체결, 국제기구 활동이 있고, 다른 나라 국민에게 우리 문화와 정책을 알리는 공공 외교도","keywords":["외교","공공 외교"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t0","kind":"term","title":"국제 사회","text":"여러 나라가 서로 관계를 맺으며 함께 살아가는 사회예요. 주권 국가가 기본 단위이고, 나라들 위의 중앙 정부가 없어요.","keywords":["국제 사회"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t1","kind":"term","title":"주권 국가","text":"다른 나라의 간섭을 받지 않고 나라의 일을 스스로 결정하는 힘(주권)을 가진 나라예요. 국제 사회의 기본 행위 주체예요.","keywords":["주권 국가"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t2","kind":"term","title":"국제법","text":"나라와 나라 사이의 관계를 규율하는 법이에요. 나라들이 맺은 조약과, 오랜 관행이 법처럼 인정된 국제 관습법 등이 있어요.","keywords":["국제법"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t3","kind":"term","title":"정부 간 국제기구","text":"여러 나라 정부가 회원이 되어 만든 국제기구예요. 예: 국제 연합(UN), 세계 무역 기구(WTO)","keywords":["정부 간 국제기구"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t4","kind":"term","title":"국제 비정부 기구","text":"여러 나라의 개인이나 시민 단체가 자발적으로 만든 국제 단체예요. 인권·환경·구호 활동을 해요. 예: 국경 없는 의사회","keywords":["국제 비정부 기구"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t5","kind":"term","title":"다국적 기업","text":"여러 나라에 공장·지사를 두고 세계적으로 생산과 판매를 하는 기업이에요.","keywords":["다국적 기업"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t6","kind":"term","title":"국제 분쟁","text":"나라나 집단 사이의 다툼이 국경을 넘어 커진 것이에요. 영토·자원·민족·종교·역사 등 여러 원인이 얽혀 일어나요.","keywords":["국제 분쟁"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t7","kind":"term","title":"동북공정","text":"중국이 고구려·발해 등 우리 고대사를 중국 지방 정권의 역사로 만들려고 한 연구 사업이에요.","keywords":["동북공정"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t8","kind":"term","title":"외교","text":"나라가 다른 나라와 관계를 맺고 대화와 협상으로 자기 나라의 이익을 지키고 넓히는 활동이에요.","keywords":["외교"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#t9","kind":"term","title":"공공 외교","text":"다른 나라 국민에게 우리 문화·가치·정책을 알려 우리나라에 대한 이해와 신뢰를 높이는 외교 활동이에요.","keywords":["공공 외교"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#f0","kind":"faq","title":"국제 사회에 정부가 없으면 국제법은 어떻게 지켜져요?","text":"국제법을 강제로 집행할 기관은 약하지만, 나라들은 대부분 국제법을 지켜요. 어기면 다른 나라와 국제기구의 비판(국제 여론)을 받고, 무역이나 협력에서 불이익을 받을 수 있기 때문이에요. 또 국제법을 지켜야 자기 나라도 다른 나라에게 같은 대우를 기대할 수 있어요.","keywords":["국제 사회","국제법"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#f1","kind":"faq","title":"정부 간 국제기구랑 국제 비정부 기구는 어떻게 구별해요?","text":"회원이 누구인지 보면 돼요. 나라(정부)가 회원이면 정부 간 국제기구(국제 연합, 세계 무역 기구 등), 개인이나 시민 단체가 자발적으로 모였으면 국제 비정부 기구(국경 없는 의사회 등)예요.","keywords":["정부 간 국제기구","국제 비정부 기구"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#f2","kind":"faq","title":"독도는 왜 우리 땅이에요?","text":"옛 기록과 지도에 독도가 우리 땅으로 나타나 있고(역사적 근거), 울릉도에서 맑은 날 눈으로 보일 만큼 가까워 예부터 울릉도 주민의 생활 공간이었어요(지리적 근거). 또 대한 제국은 1900년 칙령 제41호로 석도(독도)를 울도군(울릉도)의 관할로 밝혔고, 지금도 우리나라가 실제로 다스리고 있어요(국제법적 근거). 다음 단원에서 독도의 위치와 가치를 더 …","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#m0","kind":"mistake","title":"자주 하는 실수","text":"\"정부 간 국제기구\"와 \"국제 비정부 기구\"를 거꾸로 외우는 실수 — 회원이 나라(정부)면 정부 간, 시민·단체면 비정부예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#m1","kind":"mistake","title":"자주 하는 실수","text":"국제 분쟁의 원인을 하나만 찾는 실수 — 실제 분쟁은 영토·자원·민족·종교·역사 등 여러 원인이 얽혀 있는 경우가 많아요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-05#m2","kind":"mistake","title":"자주 하는 실수","text":"동북공정(중국)과 역사 교과서 왜곡(일본)을 바꾸어 기억하는 실수 — 어느 나라의 문제인지 함께 기억해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-05","grade":"m2"},
{"id":"soc-m-2-06","kind":"unit","title":"사회 변동과 사회 문제","text":"오늘날의 사회 변동과 사회 문제가 우리 생활에 주는 영향을 살펴보고 시민의 실천을 생각해요. 사회 변동의 의미를 알고, 세계화·지식 정보화·저출산·고령화·다문화 같은 오늘날의 사회 변동을 설명할 수 있어요. 인공 지능 등 과학 기술의 발전이 생활에 가져온 변화와 새로운 문제를 말할 수 있어요. 사회 문제의 의미와 특징을 알고, 불평등·노동·인구·기후 위기…","keywords":["사회 변동","세계화","지식 정보화","저출산","합계 출산율","고령화","다문화 사회","인공 지능","정보 격차","사회 문제"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#c0","kind":"concept","title":"사회 변동의 의미와 세계화·지식 정보화","text":"사회 변동은 시간이 흐르면서 사회의 구조, 제도, 가치관, 생활 양식이 바뀌는 현상이에요. 과학 기술의 발전, 새로운 사상과 가치관, 인구 변화, 자연환경 변화, 다른 사회와의 교류 등이 사회 변동을 일으켜요. 오늘날 우리 사회의 큰 변동 두 가지를 먼저 살펴봐요. 사회 변동 · 뜻 ·","keywords":["사회 변동","세계화","지식 정보화","정보 격차"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#c1","kind":"concept","title":"저출산·고령화와 다문화 사회","text":"저출산은 아이를 적게 낳아 출생아 수가 줄어드는 현상이에요. 여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수인 합계 출산율로 나타내요. 결혼과 출산에 대한 생각의 변화, 양육비·교육비 부담, 일과 가정을 함께 꾸리기 어려운 환경 등이 원인이에요. 고령화는 전체 인구 가운데 65세","keywords":["저출산","합계 출산율","고령화","다문화 사회"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#c2","kind":"concept","title":"과학 기술의 발전과 생활 변화","text":"인공 지능(AI)은 사람처럼 배우고, 판단하고, 문제를 해결하도록 만든 컴퓨터 기술이에요. 인공 지능과 함께 사물 인터넷, 빅데이터, 로봇 기술이 발전하면서 생활이 크게 바뀌고 있어요. 편리해진 점: 말로 기기를 다루고, 외국어를 바로 번역하며, 자율 주행 자동차가 개발되고, 의사의 진","keywords":["인공 지능","정보 격차"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#c3","kind":"concept","title":"오늘날의 사회 문제와 생활에 미치는 영향","text":"사회 문제는 사회 구성원 다수가 바람직하지 않다고 여기고, 함께 노력해 해결해야 한다고 생각하는 현상이에요. 사회 문제는 사회 구조·제도와 관련이 있고, 많은 사람에게 영향을 주며, 시대와 사회에 따라 달라지고, 사람들의 노력으로 해결할 수 있다는 특징이 있어요. 사회 문제 · 내용 ·","keywords":["저출산","고령화","사회 문제"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#c4","kind":"concept","title":"사회 변동·사회 문제에 대한 대응과 시민의 실천","text":"사회 변동과 사회 문제에 대응하려면 정부·국제 사회·시민이 함께 움직여야 해요. 국내 사례: 출산·육아를 돕는 제도(육아 휴직, 아동 수당), 노인 일자리와 돌봄 서비스, 산업 현장의 안전을 강화하는 법, 다문화 가정을 위한 한국어 교육, 온실가스를 줄이는 탄소 중립 정책 등이 있어요.","keywords":["사회 변동","저출산","사회 문제"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t0","kind":"term","title":"사회 변동","text":"시간이 흐르면서 사회의 구조·제도·가치관·생활 양식이 바뀌는 현상이에요.","keywords":["사회 변동"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t1","kind":"term","title":"세계화","text":"사람·상품·자본·정보·문화가 국경을 넘어 자유롭게 오가며 세계가 하나의 생활권이 되는 현상이에요.","keywords":["세계화"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t2","kind":"term","title":"지식 정보화","text":"지식과 정보가 가장 중요한 자원이 되어 사회를 움직이는 현상이에요. 예: 온라인 수업, 전자 상거래","keywords":["지식 정보화"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t3","kind":"term","title":"저출산","text":"아이를 적게 낳아 출생아 수가 줄어드는 현상이에요. 합계 출산율로 나타내요.","keywords":["저출산"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t4","kind":"term","title":"합계 출산율","text":"여성 한 명이 평생 낳을 것으로 예상되는 평균 자녀 수예요.","keywords":["합계 출산율"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t5","kind":"term","title":"고령화","text":"전체 인구 가운데 65세 이상 노인 인구의 비율이 높아지는 현상이에요. 7% 이상 고령화 사회, 14% 이상 고령 사회, 20% 이상 초고령 사회예요.","keywords":["고령화"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t6","kind":"term","title":"다문화 사회","text":"국제결혼, 외국인 근로자·유학생 증가 등으로 여러 문화를 가진 사람들이 함께 사는 사회예요.","keywords":["다문화 사회"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t7","kind":"term","title":"인공 지능","text":"사람처럼 배우고 판단하고 문제를 해결하도록 만든 컴퓨터 기술이에요. AI 라고도 해요.","keywords":["인공 지능"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t8","kind":"term","title":"정보 격차","text":"정보 통신 기술을 쓸 수 있는 정도에 따라 정보를 얻고 활용하는 데 차이가 생기는 것이에요.","keywords":["정보 격차"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#t9","kind":"term","title":"사회 문제","text":"사회 구성원 다수가 바람직하지 않다고 여기고, 함께 노력해 해결해야 한다고 생각하는 현상이에요.","keywords":["사회 문제"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#f0","kind":"faq","title":"사회 변동이랑 사회 문제는 뭐가 달라요?","text":"사회 변동은 사회의 모습이 시간에 따라 바뀌는 현상 자체예요. 좋고 나쁨을 따지지 않아요. 사회 문제는 많은 사람이 바람직하지 않다고 여기고 함께 해결해야 한다고 보는 현상이에요. 예를 들어 지식 정보화는 사회 변동이고, 그 과정에서 생긴 정보 격차·개인 정보 유출은 사회 문제예요.","keywords":["사회 변동","사회 문제"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#f1","kind":"faq","title":"고령화 사회랑 고령 사회는 어떻게 구별해요?","text":"65세 이상 인구 비율로 구별해요. 7% 이상이면 고령화 사회, 14% 이상이면 고령 사회, 20% 이상이면 초고령 사회예요. \"고령화 사회\"는 고령화가 시작된 단계, \"고령 사회\"는 그보다 더 나아간 단계라고 기억하면 쉬워요.","keywords":["고령화"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#f2","kind":"faq","title":"학생인 제가 사회 문제를 해결하는 데 할 수 있는 일이 있어요?","text":"물론이에요. 뉴스와 믿을 만한 자료로 사회 문제를 알아보고, 학교 캠페인이나 봉사 활동에 참여하고, 지방 자치 단체나 학생회에 의견을 낼 수 있어요. 에너지 절약, 다른 문화를 가진 친구 존중하기, 개인 정보 지키기처럼 일상의 작은 실천도 모이면 큰 힘이 돼요.","keywords":["사회 문제"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#m0","kind":"mistake","title":"자주 하는 실수","text":"\"고령화 사회\"(7% 이상)와 \"고령 사회\"(14% 이상)를 거꾸로 기억하는 실수 — 고령화 사회가 먼저 오는 앞 단계예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#m1","kind":"mistake","title":"자주 하는 실수","text":"사회 변동을 모두 나쁜 것으로 보는 실수 — 사회 변동은 편리함과 새로운 문제를 함께 가져와요. 양면을 함께 살펴봐요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-06#m2","kind":"mistake","title":"자주 하는 실수","text":"노인 인구 비율을 구할 때 65세 이상 인구를 65세 미만 인구로 나누는 실수 — 전체 인구로 나누어야 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-06","grade":"m2"},
{"id":"soc-m-2-07","kind":"unit","title":"대한민국, 우리가 사는 곳","text":"우리 국토의 위치와 영역, 행정 구역과 도시를 알고 우리 지역의 문제를 지도로 나타내요. 우리 국토의 위치를 수리적·지리적·관계적 위치로 나누어 설명하고, 지정학적·지경학적 의미를 말할 수 있어요. 독도를 포함한 우리나라의 영역(영토·영해·영공)과 배타적 경제 수역을 설명할 수 있어요. 우리나라의 행정 구역과 주요 도시의 위치를 알고, 내가 사는 곳의 장…","keywords":["수리적 위치","지리적 위치","관계적 위치","지정학적 위치","지경학적 위치","영해","영공","배타적 경제 수역","장소감","지리 정보 시스템"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c0","kind":"concept","title":"우리 국토의 위치 — 수리적·지리적·관계적 위치","text":"한 나라의 위치는 세 가지 방법으로 나타낼 수 있어요. 위치 · 나타내는 방법 · 우리나라 · 영향 수리적 위치 · 위도와 경도 · 대략 북위 33°~43°, 동경 124°~132° · 북반구 중위도라서 사계절이 뚜렷해요. 동경 135°를 표준 경선으로 써요. 지리적 위치 · 대륙·해양","keywords":["수리적 위치","지리적 위치","관계적 위치"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c1","kind":"concept","title":"지정학적·지경학적으로 본 우리나라의 위치","text":"위치가 나라에 주는 의미를 정치와 경제의 눈으로 볼 수 있어요. 지정학적 위치: 지리적 위치가 나라 사이의 정치·군사 관계에 미치는 영향으로 본 위치예요. 한반도는 대륙 세력(중국·러시아)과 해양 세력(일본·미국)이 만나는 곳이에요. 그래서 갈등이 생기면 강대국이 다투는 무대나 침략의 ","keywords":["지리적 위치","지정학적 위치","지경학적 위치"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c2","kind":"concept","title":"우리나라의 영역 — 영토·영해·영공","text":"영역은 한 나라의 주권이 미치는 범위예요. 영토·영해·영공으로 이루어져요. 영토: 주권이 미치는 땅이에요. 헌법 제3조는 \"대한민국의 영역은 한반도와 그 부속 도서로 한다.\"라고 정하고 있어요. 서·남해안에서는 간척으로 영토가 조금씩 넓어지기도 했어요. 영해: 주권이 미치는 바다로, 기","keywords":["영해","영공"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c3","kind":"concept","title":"배타적 경제 수역과 독도","text":"배타적 경제 수역(EEZ)은 영해 기선에서 200해리까지의 바다 가운데 영해를 뺀 바다예요. 이곳에서는 연안국이 물고기를 잡고 해저 자원을 탐사·개발할 수 있는 경제적 권리를 가져요. 하지만 영해와 달리 다른 나라 배가 지나가거나 비행기가 날거나 해저 케이블을 까는 것은 자유로워요. 우","keywords":["영해","배타적 경제 수역"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c4","kind":"concept","title":"행정 구역·주요 도시와 장소성","text":"행정 구역은 나라를 효율적으로 다스리기 위해 나눈 구역이에요. 우리나라(남한)는 2024년을 기준으로 17개 광역 자치 단체로 나뉘어 있어요. 구분 · 이름 특별시 (1) · 서울 광역시 (6) · 부산, 대구, 인천, 광주, 대전, 울산 특별자치시 (1) · 세종 도 (6) · 경기도","keywords":["장소감"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#c5","kind":"concept","title":"우리 지역 문제를 지리 정보로 나타내기","text":"지리 정보는 어떤 장소나 지역에 대한 정보예요. 세 가지로 나눌 수 있어요. 공간 정보: 위치와 형태 (예: 놀이터가 어디에 있는지) 속성 정보: 그 장소의 특성 (예: 놀이터의 넓이, 놀이 기구 수) 관계 정보: 다른 장소와의 관계 (예: 놀이터와 초등학교 사이의 거리) 지리 정보는 ","keywords":["지리 정보 시스템"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t0","kind":"term","title":"수리적 위치","text":"위도와 경도로 나타낸 위치예요. 우리나라는 대략 북위 33°~43°, 동경 124°~132°에 있어요.","keywords":["수리적 위치"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t1","kind":"term","title":"지리적 위치","text":"대륙·해양·반도 같은 지형지물로 나타낸 위치예요. 예: 유라시아 대륙 동쪽 끝의 반도","keywords":["지리적 위치"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t2","kind":"term","title":"관계적 위치","text":"주변 나라와의 관계로 나타낸 위치예요. 주변 나라와의 관계에 따라 시대마다 바뀌어요.","keywords":["관계적 위치"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t3","kind":"term","title":"지정학적 위치","text":"지리적 위치가 나라 사이의 정치·군사 관계에 미치는 영향으로 본 위치예요.","keywords":["지정학적 위치"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t4","kind":"term","title":"지경학적 위치","text":"지리적 위치가 나라 사이의 경제 관계에 미치는 영향으로 본 위치예요.","keywords":["지경학적 위치"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t5","kind":"term","title":"영해","text":"한 나라의 주권이 미치는 바다예요. 우리나라는 대부분 기선에서 12해리까지예요(대한 해협은 3해리).","keywords":["영해"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t6","kind":"term","title":"영공","text":"영토와 영해 위의 하늘이에요. 일반적으로 대기권까지로 봐요.","keywords":["영공"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t7","kind":"term","title":"배타적 경제 수역","text":"영해 기선에서 200해리까지의 바다 가운데 영해를 뺀 바다예요. 연안국이 어업·자원 개발 같은 경제적 권리를 가져요. EEZ 라고도 해요.","keywords":["배타적 경제 수역"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t8","kind":"term","title":"장소감","text":"한 사람이 어떤 장소에 대해 느끼는 감정이나 애착이에요.","keywords":["장소감"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#t9","kind":"term","title":"지리 정보 시스템","text":"지리 정보를 컴퓨터에 저장·분석해 지도 등으로 나타내는 시스템이에요. GIS 라고도 해요.","keywords":["지리 정보 시스템"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#f0","kind":"faq","title":"우리나라 표준 경선(동경 135°)은 우리 땅을 지나지 않는데 왜 그걸 써요?","text":"우리 국토는 대략 동경 124°~132°에 있어서 가운데쯤은 동경 127.5° 근처예요. 그런데 표준시는 보통 경도 15°의 배수를 기준으로 정해 세계 시각과 1시간 단위로 맞추기 편하게 해요. 그래서 우리나라는 가까운 15°의 배수인 동경 135°를 표준 경선으로 써요. 그 결과 우리나라의 시계는 실제 해의 움직임보다 30분쯤 빨라요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#f1","kind":"faq","title":"영해랑 배타적 경제 수역은 뭐가 달라요?","text":"영해(12해리)는 나라의 주권이 완전히 미치는 바다라서 다른 나라 배가 함부로 들어와 활동할 수 없어요(해를 끼치지 않고 지나가는 것은 인정해요). 배타적 경제 수역(200해리까지, 영해 제외)은 경제적 권리만 가지는 바다라서 물고기 잡기·자원 개발은 연안국이 권리를 가지지만, 다른 나라 배의 항해나 비행은 자유로워요.","keywords":["영해","배타적 경제 수역"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#f2","kind":"faq","title":"장소감이랑 장소성은 어떻게 구별해요?","text":"장소감은 한 사람이 느끼는 마음(그곳에 가면 편안하다, 그립다)이고, 장소성은 그 장소가 가진 고유한 특징과 사람들이 함께 부여한 의미(전통 시장의 활기, 역사 깊은 골목)예요. \"나의 느낌\"인지 \"그 장소의 특징\"인지로 구별해 보세요.","keywords":["장소감"],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#m0","kind":"mistake","title":"자주 하는 실수","text":"영공을 영토 위의 하늘만이라고 생각하는 실수 — 영공은 영토와 영해 위의 하늘이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#m1","kind":"mistake","title":"자주 하는 실수","text":"배타적 경제 수역을 \"200해리까지 모두 우리 바다(영해)\"로 생각하는 실수 — 영해를 뺀 바다이고, 경제적 권리만 가져요. 다른 나라 배의 항해는 자유로워요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-07#m2","kind":"mistake","title":"자주 하는 실수","text":"동경과 서경 사이의 시차를 구할 때 경도를 빼는 실수 — 본초 자오선을 사이에 두고 있으면 경도를 더해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-07","grade":"m2"},
{"id":"soc-m-2-08","kind":"unit","title":"국토의 자연환경과 생활","text":"우리나라의 지형과 기후의 특성을 알아보고, 기후 변화와 자연재해에 대한 대응을 살펴봐요. 우리나라 주요 산지·하천의 위치와 특성을 설명할 수 있어요. 해안 지형(갯벌·모래 해안·암석 해안)과 화산 지형·카르스트 지형의 특징과 가치를 말할 수 있어요. 우리나라의 계절별·지역별 기후 특성과 기후 변화 양상, 이에 대한 대응 노력을 설명할 수 있어요. 자연재해…","keywords":["동고서저","갯벌","사빈","석호","해식애","주상 절리","카르스트 지형","기온의 연교차","계절풍","내진 설계"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c0","kind":"concept","title":"산지와 하천","text":"우리나라는 국토의 약 70%가 산지예요. 오랫동안 깎여 나가(침식) 낮고 완만한 산이 많고, 높은 산은 주로 북쪽과 동쪽에 있어요. 동고서저: 동쪽은 높고 서쪽은 낮은 지형이에요. 동쪽에는 태백산맥처럼 높은 산줄기가 해안 가까이 이어지고, 서쪽으로 갈수록 낮아져 평야가 넓어요. 백두대간","keywords":["동고서저"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c1","kind":"concept","title":"해안 지형 — 갯벌·모래 해안·암석 해안","text":"우리나라는 삼면이 바다라서 해안마다 모습이 달라요. 해안 · 특징 서해안·남해안 · 해안선이 매우 복잡하고 섬이 많아요. 서해안은 밀물과 썰물의 차이(조차)가 커서 갯벌이 넓게 발달했어요. 동해안 · 해안선이 단조롭고 섬이 적으며 수심이 깊어요. 모래 해안과 암석 해안이 발달했어요. 갯","keywords":["갯벌","사빈"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c2","kind":"concept","title":"매력적인 지형 경관 — 화산 지형과 카르스트 지형","text":"화산 지형은 땅속의 마그마가 땅 위로 분출해 만들어진 지형이에요. 제주도: 섬 가운데에 한라산이 있고 꼭대기에 화구호인 백록담이 있어요. 섬 곳곳에 작은 화산인 오름이 있고, 용암이 흘러가며 만든 용암 동굴, 용암이 식으면서 수축해 생긴 기둥 모양의 주상 절리가 있어요. 2007년 '제","keywords":["주상 절리","카르스트 지형"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c3","kind":"concept","title":"계절별·지역별 기후 특성","text":"우리나라는 중위도에 있어 사계절이 뚜렷하고, 대륙의 동쪽에 있어 여름과 겨울의 기온 차(기온의 연교차)가 커요. 계절에 따라 바람의 방향이 바뀌는 계절풍의 영향을 크게 받아요. 계절 · 특징 봄 · 날씨가 자주 바뀌고 건조해요. 꽃샘추위와 황사가 나타나요. 여름 · 남쪽에서 덥고 습한 ","keywords":["기온의 연교차","계절풍"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c4","kind":"concept","title":"기후 변화 양상과 대응","text":"기후 변화는 오랜 기간에 걸쳐 기후가 바뀌는 것이에요. 오늘날에는 화석 연료 사용 등으로 온실가스가 늘어 지구의 평균 기온이 오르는 지구 온난화가 큰 문제예요. 우리나라도 지난 100여 년 동안 연평균 기온이 1℃ 넘게 올랐어요. 우리나라에 나타나는 변화 여름이 길어지고 겨울이 짧아졌어","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#c5","kind":"concept","title":"자연재해와 나의 대처","text":"자연재해는 자연 현상 때문에 사람의 생명과 재산에 피해가 생기는 것이에요. 자연재해 · 지리적 특성 홍수 · 여름 장마·집중 호우·태풍 때 하천이 넘치거나 낮은 땅이 물에 잠겨요. 태풍 · 주로 여름~초가을에 열대 바다에서 발생해 강한 바람과 많은 비, 해일을 몰고 와요. 남해안·제주도","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t0","kind":"term","title":"동고서저","text":"동쪽은 높고 서쪽은 낮은 우리나라의 지형 특징이에요. 그래서 큰 하천이 대부분 서해와 남해로 흘러요.","keywords":["동고서저"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t1","kind":"term","title":"갯벌","text":"밀물 때 바닷물에 잠기고 썰물 때 드러나는 평평한 진흙·모래 땅이에요. 조차가 큰 서해안에 넓게 발달했어요.","keywords":["갯벌"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t2","kind":"term","title":"사빈","text":"파도와 바닷물의 흐름이 모래를 쌓아 만든 모래사장이에요. 해수욕장으로 많이 쓰여요.","keywords":["사빈"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t3","kind":"term","title":"석호","text":"모래가 만의 입구를 막아 생긴 호수예요. 동해안에 있어요.","keywords":["석호"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t4","kind":"term","title":"해식애","text":"파도가 바위를 깎아 만든 해안 절벽이에요.","keywords":["해식애"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t5","kind":"term","title":"주상 절리","text":"용암이 식으면서 수축해 생긴 기둥 모양의 바위 틈이에요. 제주도 해안과 한탄강 주변에서 볼 수 있어요.","keywords":["주상 절리"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t6","kind":"term","title":"카르스트 지형","text":"석회암이 빗물과 지하수에 녹아 만들어진 지형이에요. 석회 동굴, 돌리네가 있어요.","keywords":["카르스트 지형"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t7","kind":"term","title":"기온의 연교차","text":"가장 따뜻한 달의 평균 기온에서 가장 추운 달의 평균 기온을 뺀 값이에요.","keywords":["기온의 연교차"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t8","kind":"term","title":"계절풍","text":"계절에 따라 방향이 바뀌는 바람이에요. 우리나라는 여름에 남쪽, 겨울에 북서쪽에서 불어요.","keywords":["계절풍"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#t9","kind":"term","title":"내진 설계","text":"지진이 일어나도 건물이 무너지지 않고 견디도록 설계하는 것이에요.","keywords":["내진 설계"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#f0","kind":"faq","title":"우리나라 큰 강은 왜 다 서쪽으로 흘러요?","text":"우리나라는 동쪽이 높고 서쪽이 낮은 동고서저 지형이에요. 물은 높은 곳에서 낮은 곳으로 흐르니까, 높은 산줄기가 있는 동쪽에서 시작해 낮은 서쪽(황해)과 남쪽(남해)으로 길게 흘러가요. 동해 쪽은 산줄기가 해안 가까이 있어서 하천이 짧고 가팔라요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#f1","kind":"faq","title":"태풍은 피해만 주나요?","text":"강한 바람과 많은 비로 큰 피해를 주지만 이로운 점도 있어요. 많은 비를 내려 가뭄을 풀어 주고, 바닷물을 뒤섞어 적조를 줄이며, 열대 지방의 열을 다른 곳으로 옮겨 지구의 열 균형을 맞추는 데 도움을 줘요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#f2","kind":"faq","title":"지진이 나면 왜 엘리베이터를 타면 안 돼요?","text":"지진으로 전기가 끊기거나 엘리베이터가 고장 나면 안에 갇힐 수 있어요. 흔들림이 멈춘 뒤 계단으로 이동해 운동장·공원처럼 건물에서 떨어진 넓은 곳으로 대피해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#m0","kind":"mistake","title":"자주 하는 실수","text":"석회 동굴과 용암 동굴을 헷갈리는 실수 — 석회 동굴은 석회암이 물에 녹아 생긴 카르스트 지형(강원 남부 등), 용암 동굴은 용암이 흘러 생긴 화산 지형(제주도)이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#m1","kind":"mistake","title":"자주 하는 실수","text":"기온의 연교차를 구할 때 음수를 빼는 것을 잘못하는 실수 — 25 − (−6)은 25 + 6 = 31이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-08#m2","kind":"mistake","title":"자주 하는 실수","text":"완화와 적응을 헷갈리는 실수 — 온실가스를 줄이는 것은 완화, 바뀐 기후에 맞춰 피해를 줄이는 것은 적응이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-08","grade":"m2"},
{"id":"soc-m-2-09","kind":"unit","title":"중부 지역","text":"수도권과 강원·충청 지역의 특성과 변화를 살펴보고, 지역 불균형을 줄이는 방안을 생각해요. 중부 지역(수도권·강원·충청)의 위치와 자연·인문 환경의 특징을 말할 수 있어요. 수도권의 공간 구조와 인구·문화·경제의 변화를 설명할 수 있어요. 교통 발달과 산업 변화가 강원·충청 지역에 가져온 변화를 설명할 수 있어요. 수도권과 비수도권의 지역 불균형 문제와 …","keywords":["수도권","영동·영서","인구 공동화 현상","위성 도시","개발 제한 구역","빨대 효과","고랭지 농업","혁신 도시","장소 마케팅"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c0","kind":"concept","title":"중부 지역의 모습과 매력적인 장소","text":"중부 지역은 한반도의 가운데 부분으로, 크게 세 지역으로 나누어 살펴봐요. 지역 · 포함하는 곳 · 자연환경의 특징 수도권 · 서울특별시·인천광역시·경기도 · 한강 하류의 넓은 평야와 낮은 구릉, 서해의 갯벌과 섬 강원 지역 · 강원특별자치도 · 땅의 대부분이 산지예요. 태백산맥을 경계","keywords":["수도권"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c1","kind":"concept","title":"수도권의 공간 구조","text":"수도권은 서울을 중심으로 인천과 경기도가 하나의 큰 생활권을 이루는 곳이에요. 국토 면적의 약 12%밖에 안 되지만, 우리나라 사람의 절반 정도가 여기에 살아요. 서울의 내부 도심: 서울의 한가운데로, 관청·큰 회사의 본사·백화점처럼 중심 기능이 모여 있어요. 땅값이 매우 비싸서 주택은","keywords":["수도권","인구 공동화 현상","위성 도시"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c2","kind":"concept","title":"수도권의 인구·문화·경제 변화","text":"인구의 변화 1960~1980년대 산업화가 이루어지면서 일자리를 찾아 많은 사람이 농촌에서 서울로 옮겨 왔어요. 1990년대 이후에는 서울의 집값과 혼잡을 피해 경기도와 인천으로 옮겨 가는 사람이 늘었어요. 서울의 인구는 조금씩 줄고 경기도의 인구는 크게 늘어, 지금은 경기도의 인구가 ","keywords":["수도권"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c3","kind":"concept","title":"교통 발달과 강원·충청 지역의 변화","text":"고속 도로와 고속 철도가 생기면서 강원·충청 지역과 수도권 사이의 시간 거리가 크게 줄었어요. 강원 지역 예전에는 태백산맥을 넘기 어려워 서울에서 동해안까지 오래 걸렸어요. 영동 고속 도로가 넓어지고, 서울과 양양을 잇는 고속 도로, 서울과 강릉을 잇는 고속 철도가 생겨 동해안이 훨씬 ","keywords":["수도권"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c4","kind":"concept","title":"강원·충청 지역의 산업 변화와 지역 경제 활성화","text":"강원 지역 1960~1980년대에는 태백·정선·영월 등에서 석탄 산업이 번성했어요. 그런데 석유·가스를 많이 쓰게 되면서 석탄 수요가 줄었고, 1989년 무렵부터 정부가 경제성이 낮은 탄광을 정리하자 많은 탄광이 문을 닫았어요. 일자리를 잃은 사람들이 떠나 인구가 크게 줄었어요. 그 뒤","keywords":["고랭지 농업"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#c5","kind":"concept","title":"수도권과 비수도권의 지역 불균형","text":"사람·일자리·돈이 한 지역에 몰리면 지역 불균형이 생겨요. 우리나라는 수도권에 지나치게 많은 것이 모여 있어요. 수도권의 문제(과밀) · 비수도권의 문제(과소) 비싼 집값, 교통 혼잡 · 젊은 사람이 떠나 인구가 줄고 고령화가 빨라요 대기 오염, 쓰레기 처리 문제 · 일자리·병원·학교·","keywords":["수도권","혁신 도시"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t0","kind":"term","title":"수도권","text":"서울특별시·인천광역시·경기도를 함께 이르는 말이에요. 국토 면적은 좁지만 우리나라 사람의 절반 정도가 살아요.","keywords":["수도권"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t1","kind":"term","title":"영동·영서","text":"강원 지역을 태백산맥을 경계로 나눈 이름이에요. 산맥의 동쪽이 영동, 서쪽이 영서예요.","keywords":["영동·영서"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t2","kind":"term","title":"인구 공동화 현상","text":"도심처럼 낮에는 사람이 많지만 밤에는 주거 인구가 적어 텅 비는 현상이에요.","keywords":["인구 공동화 현상"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t3","kind":"term","title":"위성 도시","text":"큰 도시 둘레에서 주거·공업·행정 같은 기능을 나누어 맡는 도시예요.","keywords":["위성 도시"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t4","kind":"term","title":"개발 제한 구역","text":"도시가 끝없이 퍼지는 것을 막고 자연을 지키려고 개발을 제한한 구역이에요. 그린벨트라고도 해요.","keywords":["개발 제한 구역"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t5","kind":"term","title":"빨대 효과","text":"교통이 좋아진 뒤 작은 지역의 사람·돈·상권이 큰 도시로 빨려 가는 현상이에요.","keywords":["빨대 효과"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t6","kind":"term","title":"고랭지 농업","text":"여름에도 서늘한 높은 지대에서 배추·무 같은 채소를 기르는 농업이에요. 강원의 대관령 일대가 대표적이에요.","keywords":["고랭지 농업"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t7","kind":"term","title":"혁신 도시","text":"수도권의 공공 기관을 지방으로 옮기고, 그 둘레에 새로 만든 도시예요.","keywords":["혁신 도시"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#t8","kind":"term","title":"장소 마케팅","text":"지역의 자연·역사·문화 같은 매력을 알려 관광객과 기업을 끌어들이는 전략이에요.","keywords":["장소 마케팅"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#f0","kind":"faq","title":"서울 둘레에 왜 개발 제한 구역을 두었어요? 집을 더 지으면 좋지 않아요?","text":"도시가 둘레로 끝없이 퍼지면 숲과 농지가 사라지고, 도시와 도시가 붙어 버려 환경이 나빠져요. 개발 제한 구역은 도시 사이에 녹지를 남겨 맑은 공기와 쉼터를 지키는 역할을 해요. 다만 집이 부족할 때 일부를 풀어 개발할지를 두고는 여러 의견이 있어요.","keywords":["개발 제한 구역"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#f1","kind":"faq","title":"세종에 정부 부처가 옮겨 가면 수도권 문제가 다 해결돼요?","text":"한 가지 정책만으로는 해결되지 않아요. 행정 기능을 나누는 것은 시작이고, 기업·대학·병원·문화 시설 같은 사람이 머무를 이유가 지방에도 함께 생겨야 해요. 그래서 혁신 도시, 기업 도시, 지방의 교통·교육 개선처럼 여러 정책을 함께 쓰고 있어요.","keywords":["수도권"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#f2","kind":"faq","title":"영동 지방은 겨울에 왜 영서 지방보다 따뜻해요?","text":"겨울에 부는 차가운 북서풍을 높은 태백산맥이 막아 주고, 겨울에도 비교적 따뜻한 동해의 영향을 받기 때문이에요. 대신 동해에서 불어오는 바람이 산에 부딪히면 눈구름이 생겨 영동 지방에 눈이 많이 내리기도 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#m0","kind":"mistake","title":"자주 하는 실수","text":"대전·세종을 수도권으로 착각하는 실수 — 수도권은 서울·인천·경기뿐이고, 대전·세종은 충청 지역이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-09#m1","kind":"mistake","title":"자주 하는 실수","text":"도심은 사람이 많으니 사는 사람도 많다고 여기는 실수 — 도심은 낮에 일하러 온 사람이 많을 뿐, 땅값이 비싸 주거 인구는 적어요(인구 공동화 현상).","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-09","grade":"m2"},
{"id":"soc-m-2-10","kind":"unit","title":"남부 지역","text":"영남·호남 지역의 산업과 변화, 제주도의 변화를 살펴보며 남부 지역의 매력과 과제를 알아봐요. 남부 지역(영남·호남·제주)의 자연·인문 환경과 매력적인 장소를 말할 수 있어요. 영남·호남 공업 지역의 주요 산업과 우리나라 산업에서 차지하는 위상을 설명할 수 있어요. 영남·호남 지역의 산업 변화와 앞으로 풀어야 할 과제를 설명할 수 있어요. 관광 산업과 기…","keywords":["남동 임해 공업 지역","중화학 공업","곡창 지대","갯벌","오름","현무암","용천수","아열대 작물","탄소 중립"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c0","kind":"concept","title":"남부 지역의 모습과 매력적인 장소","text":"남부 지역은 한반도의 남쪽으로, 영남·호남·제주로 나누어 살펴봐요. 지역 · 포함하는 곳 · 자연환경의 특징 영남 지역 · 부산·대구·울산광역시, 경상북도·경상남도 · 소백산맥 동남쪽, 낙동강 유역. 대구는 분지라서 여름에 매우 더워요 호남 지역 · 광주광역시, 전북특별자치도·전라남도 ","keywords":["갯벌","오름"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c1","kind":"concept","title":"영남 공업 지역의 위상과 주요 산업","text":"영남 지역의 남동쪽 바닷가에는 큰 공업 도시들이 이어져 있어요. 이것을 남동 임해 공업 지역이라고 해요(임해: 바다에 닿아 있다는 뜻). 이곳에 공업이 발달한 까닭 1970년대 정부가 중화학 공업을 키우면서 이곳에 큰 공업 단지를 만들었어요. 바닷가라서 철광석·원유 같은 원료를 배로 들","keywords":["남동 임해 공업 지역","중화학 공업"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c2","kind":"concept","title":"호남 지역의 농업과 공업","text":"농업: 호남 지역은 호남평야·나주평야처럼 넓고 평평한 들이 많아 예로부터 쌀이 많이 나는 곡창 지대였어요. 서남해안의 넓은 갯벌에서는 김·굴·꼬막 같은 수산물을 기르고 거둬요. 공업: 호남은 영남보다 늦게, 1980년대 무렵부터 공업이 본격적으로 성장했어요. 도시 · 대표 공업 여수 ·","keywords":["곡창 지대","갯벌"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c3","kind":"concept","title":"영남·호남 지역의 산업 변화와 과제","text":"남부 지역의 공업은 우리나라 경제 성장을 이끌었지만, 지금은 여러 변화와 과제를 마주하고 있어요. 산업의 어려움 세계 경기가 나빠지고 다른 나라와의 경쟁이 치열해지면 배·철강 같은 산업이 크게 흔들려요. 2010년대에는 조선업이 불황을 겪어 거제·울산 등에서 일자리가 크게 줄었고, 군산","keywords":["탄소 중립"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c4","kind":"concept","title":"제주도의 자연과 관광 산업의 변화","text":"화산섬 제주의 자연과 생활 섬 가운데에 한라산이 솟아 있고, 둘레에 작은 화산인 오름이 수백 개 흩어져 있어요. 땅을 이루는 현무암은 구멍과 틈이 많아 빗물이 땅속으로 잘 스며들어요. 그래서 비가 많이 와도 대부분의 하천은 평소에 물이 없는 건천이고, 논농사가 어려워 밭농사와 감귤 재배","keywords":["오름","현무암","용천수"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#c5","kind":"concept","title":"기후 변화와 제주를 둘러싼 다양한 가치","text":"기후 변화로 달라지는 제주 기온이 오르면서 망고·바나나 같은 아열대 작물을 기르는 농가가 늘었어요. 제주에서만 잘 자라던 감귤도 이제는 남해안 등 육지의 더 넓은 곳에서 기를 수 있게 되었어요. 바다의 수온이 오르면서 따뜻한 바다에 사는 물고기가 늘고, 해조류가 사라져 바닷속이 하얗게 ","keywords":["아열대 작물"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t0","kind":"term","title":"남동 임해 공업 지역","text":"영남 지역 남동쪽 바닷가를 따라 울산·포항·거제·창원 등 공업 도시가 이어진 지역이에요. 원료 수입과 제품 수출에 유리해요.","keywords":["남동 임해 공업 지역"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t1","kind":"term","title":"중화학 공업","text":"철강·조선·자동차·석유 화학처럼 크고 무거운 제품이나 화학 제품을 만드는 공업이에요.","keywords":["중화학 공업"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t2","kind":"term","title":"곡창 지대","text":"넓은 평야에서 쌀 같은 곡식이 많이 나는 지역이에요. 호남평야가 대표적이에요.","keywords":["곡창 지대"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t3","kind":"term","title":"갯벌","text":"밀물 때는 바닷물에 잠기고 썰물 때는 드러나는 넓은 진흙 땅이에요. 서해안과 남해안에 넓게 펼쳐져 있어요.","keywords":["갯벌"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t4","kind":"term","title":"오름","text":"제주도에서 한라산 둘레에 흩어진 작은 화산을 부르는 말이에요.","keywords":["오름"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t5","kind":"term","title":"현무암","text":"용암이 식어서 굳은 검은 돌이에요. 구멍이 많고, 제주도의 돌담과 집에 많이 쓰여요.","keywords":["현무암"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t6","kind":"term","title":"용천수","text":"땅속으로 스며든 빗물이 바닷가 같은 곳에서 다시 솟아나는 물이에요. 제주에서는 이 물 가까이에 마을이 생겼어요.","keywords":["용천수"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t7","kind":"term","title":"아열대 작물","text":"열대와 온대 사이의 따뜻한 기후에서 잘 자라는 작물이에요. 망고·바나나 등이 있어요.","keywords":["아열대 작물"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#t8","kind":"term","title":"탄소 중립","text":"온실가스를 내보내는 양을 최대한 줄이고, 남은 양은 숲 등으로 흡수해 실제 배출량을 0으로 만드는 것이에요.","keywords":["탄소 중립"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#f0","kind":"faq","title":"왜 공장들이 바닷가에 많이 있어요? 내륙에 지으면 안 돼요?","text":"제철·석유 화학·조선 같은 공업은 무거운 원료를 많이 쓰는데, 우리나라는 그 원료를 대부분 배로 수입해요. 바닷가에 지으면 원료를 바로 내려 쓰고 제품도 바로 수출할 수 있어 운송비가 크게 줄어요. 반면 전자 제품처럼 가볍고 비싼 제품을 만드는 공장은 내륙(구미 등)에도 많이 있어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#f1","kind":"faq","title":"제주도에 관광객이 많이 오면 좋은 거 아니에요?","text":"관광객이 오면 일자리와 소득이 늘어 좋은 점이 많아요. 하지만 섬이 감당할 수 있는 양보다 많은 사람이 오면 쓰레기·물 부족·교통 혼잡·집값 상승 같은 문제가 생기고, 자연이 망가지면 관광객이 찾을 매력도 사라져요. 그래서 관광객 수를 늘리는 것보다 관광의 질과 환경을 함께 생각하는 것이 중요해요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#f2","kind":"faq","title":"제주도는 비가 많이 온다는데 왜 물이 부족할 수 있어요?","text":"제주도는 비가 많이 오지만 빗물이 현무암 틈으로 땅속에 스며들어 하천에 거의 고이지 않아요. 그래서 제주 사람들은 주로 지하수를 써요. 관광객과 인구가 늘어 지하수를 너무 많이 뽑거나 오염시키면 깨끗한 물이 부족해질 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#m0","kind":"mistake","title":"자주 하는 실수","text":"여수·광양을 영남 지역으로 착각하는 실수 — 여수(석유 화학)와 광양(제철)은 전라남도, 곧 호남 지역이에요. 포항(제철)·울산·거제가 영남이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-10#m1","kind":"mistake","title":"자주 하는 실수","text":"비가 많이 오는 제주도에는 강과 논이 많을 것이라고 생각하는 실수 — 빗물이 현무암 틈으로 스며들어 하천은 대부분 건천이고, 밭농사가 발달했어요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-10","grade":"m2"},
{"id":"soc-m-2-11","kind":"unit","title":"북부 지역과 한반도 평화","text":"북한의 자연과 인문 환경, 분단과 접경 지역의 모습을 살펴보고 한반도 평화를 생각해요. 북한의 지형·기후와 인구·도시·산업의 특징을 설명할 수 있어요. 분단이 우리의 일상생활과 국토 공간에 미친 영향을 말할 수 있어요. 접경 지역이 분리와 연결의 공간임을 한반도와 세계의 사례로 비교할 수 있어요. 한반도 평화가 왜 중요한지 말하고, 통일 국토의 미래를 구…","keywords":["개마고원","백두산","협동 농장","다락밭","경제특구","비무장 지대(DMZ)","접경 지역","이산가족","분단 비용","통일 편익"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c0","kind":"concept","title":"북한의 자연환경 — 지형과 기후","text":"북한은 한반도의 북쪽 지역으로, 면적은 남한보다 조금 넓어요. 지형 북부와 북동부에는 높고 험한 산지가 많아요. 평균 높이가 매우 높아 \"한반도의 지붕\"이라 불리는 개마고원이 있어요. 한반도에서 가장 높은 백두산은 화산으로, 꼭대기에 화산 분화구에 물이 고인 호수 천지가 있어요. 서쪽으","keywords":["개마고원","백두산"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c1","kind":"concept","title":"북한의 인구와 도시","text":"인구: 북한의 인구는 약 2,500만 명으로, 남한 인구의 절반 정도예요. 사람들은 주로 서쪽의 평야 지역(평양·남포 일대)과 해안의 도시에 모여 살고, 북동부의 높은 산지에는 인구가 적어요. 주요 도시 도시 · 특징 평양 · 북한의 수도이자 가장 큰 도시. 정치·경제·문화의 중심지예요","keywords":["경제특구"],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c2","kind":"concept","title":"북한의 산업과 교통","text":"지하자원과 공업 북한에는 석탄·철광석·마그네사이트 같은 지하자원이 풍부하고, 산지의 큰 하천을 이용한 수력 발전도 많이 해요. 북한은 오랫동안 기계·금속 같은 중화학 공업을 우선해서 키웠어요. 그 대신 옷·신발·생활용품을 만드는 경공업에는 투자가 적어, 주민들의 생활용품이 부족했어요. ","keywords":["협동 농장","다락밭"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c3","kind":"concept","title":"분단이 우리의 일상생활에 미친 영향","text":"1945년 광복 뒤 남북이 나뉘고, 6·25 전쟁(1950~1953)이 정전 협정으로 멈춘 뒤 지금까지 분단이 이어지고 있어요. 분단은 우리 생활 곳곳에 영향을 주어요. 가족의 이별: 전쟁과 분단으로 가족과 헤어진 이산가족이 있어요. 많은 분이 나이가 많아 세상을 떠나고 있어 만남이 더","keywords":["이산가족","분단 비용"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c4","kind":"concept","title":"분리와 연결의 공간, 접경 지역","text":"접경 지역은 두 나라나 지역의 경계와 맞닿은 곳이에요. 접경 지역은 사람과 물건을 막는 곳(분리)이 되기도 하고, 서로 만나는 곳(연결)이 되기도 해요. 한반도의 접경 지역 6·25 전쟁의 정전으로 그어진 군사 분계선(휴전선)을 사이에 두고, 남북으로 각각 2 km 범위에 군사 시설을 ","keywords":["비무장 지대(DMZ)","접경 지역"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#c5","kind":"concept","title":"한반도 평화와 통일 국토의 미래","text":"평화가 중요한 까닭 전쟁의 위험과 불안에서 벗어나 모두가 안전하게 살 수 있어요. 많은 국방비 같은 분단 비용을 줄여 교육·복지 등에 쓸 수 있어요. 이산가족의 아픔을 덜고, 남북의 사람들이 자유롭게 오갈 수 있어요. 한반도의 평화는 동아시아와 세계의 평화에도 도움이 돼요. 통일 국토의","keywords":["이산가족","분단 비용"],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t0","kind":"term","title":"개마고원","text":"북한 북부에 있는 높고 넓은 고원이에요. 평균 높이가 매우 높아 \"한반도의 지붕\"이라고 불려요.","keywords":["개마고원"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t1","kind":"term","title":"백두산","text":"한반도에서 가장 높은 산으로, 화산이에요. 꼭대기에 천지라는 호수가 있어요.","keywords":["백두산"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t2","kind":"term","title":"협동 농장","text":"북한에서 농민들이 함께 농사짓고 생산물을 나누는 농장이에요.","keywords":["협동 농장"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t3","kind":"term","title":"다락밭","text":"산비탈을 계단 모양으로 깎아 만든 밭이에요. 북한에서 많이 만들어 숲이 줄고 홍수 피해가 커졌어요.","keywords":["다락밭"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t4","kind":"term","title":"경제특구","text":"외국의 돈과 기술을 끌어들이려고 세금·규제 등에서 특별한 혜택을 주는 지역이에요. 북한의 나선이 대표적이에요.","keywords":["경제특구"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t5","kind":"term","title":"비무장 지대(DMZ)","text":"군사 분계선을 사이에 두고 남북으로 각각 2 km 범위에 군사 시설을 두지 않기로 한 지역이에요.","keywords":["비무장 지대(DMZ)"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t6","kind":"term","title":"접경 지역","text":"두 나라나 지역의 경계와 맞닿은 지역이에요. 분리의 공간이자 연결의 공간이 될 수 있어요.","keywords":["접경 지역"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t7","kind":"term","title":"이산가족","text":"전쟁과 분단 때문에 서로 헤어져 소식을 모르거나 만나지 못하는 가족이에요.","keywords":["이산가족"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t8","kind":"term","title":"분단 비용","text":"분단 때문에 치르는 비용이에요. 많은 국방비, 전쟁 위험에 대한 불안, 이산가족의 아픔 등이 있어요.","keywords":["분단 비용"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#t9","kind":"term","title":"통일 편익","text":"통일이 되었을 때 얻을 수 있는 이익이에요. 분단 비용이 사라지고, 경제·교통·문화 교류가 넓어져요.","keywords":["통일 편익"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#f0","kind":"faq","title":"북한 사람들과 말이 통해요?","text":"네, 같은 우리말을 쓰기 때문에 대부분 통해요. 다만 오랫동안 떨어져 살면서 낱말과 억양이 조금씩 달라졌어요. 북한에서는 외래어를 우리말로 바꾸어 쓰는 경우가 많아서, 도시락을 곽밥, 볼펜을 원주필이라고 해요. 그래서 남북의 낱말을 함께 정리하는 사전을 만들려는 노력도 있었어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#f1","kind":"faq","title":"휴전선과 군사 분계선은 같은 거예요?","text":"네, 흔히 같은 뜻으로 써요. 6·25 전쟁을 멈추는 정전 협정(1953년)에 따라 남북을 가른 선이 군사 분계선이고, 이를 휴전선이라고도 불러요. 이 선에서 남북으로 각각 2 km 범위가 비무장 지대예요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#f2","kind":"faq","title":"통일이 되면 돈이 많이 든다는데 왜 통일을 이야기해요?","text":"통일 과정에 큰 비용이 들 수 있다는 걱정은 실제로 있어요. 하지만 분단이 이어지는 동안에도 국방비, 전쟁 위험, 이산가족의 아픔 같은 분단 비용을 계속 치르고 있어요. 또 통일이 되면 대륙으로 가는 길이 열리고 남북이 서로 부족한 점을 채우는 등 통일 편익도 생겨요. 그래서 비용과 편익을 함께 따져 보고, 무엇보다 평화를 지키며 차근차근 준비하자는 것이…","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#m0","kind":"mistake","title":"자주 하는 실수","text":"비무장 지대와 민간인 통제선을 같은 것으로 헷갈리는 실수 — 비무장 지대는 군사 분계선에서 남북 각각 2 km 범위이고, 민간인 통제선은 그 남쪽에서 민간인 출입을 통제하는 선이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-11#m1","kind":"mistake","title":"자주 하는 실수","text":"북한의 중심 교통수단을 도로라고 생각하는 실수 — 북한은 산지가 많아 철도가 중심이고 도로가 보조 역할을 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-11","grade":"m2"},
{"id":"soc-m-2-12","kind":"unit","title":"지속가능한 세계와 글로컬 시민","text":"자원과 환경 문제를 살펴보고, 더 나은 지역과 세계를 만들기 위해 실천하는 방법을 찾아요. 우리나라의 식량 자원과 에너지 자원의 소비·수입 현황을 설명할 수 있어요. 자원 문제의 원인을 알고, 지속가능한 자원 확보 방안을 제시할 수 있어요. 지역 개발과 환경 보존을 둘러싼 글로컬 환경 이슈를 여러 관점에서 살펴볼 수 있어요. 더 나은 지역을 만드는 사례를…","keywords":["식량 자급률","식량 안보","푸드 마일리지","로컬 푸드","자원의 편재성","자원 민족주의","신·재생 에너지","지속가능한 발전","글로컬","생태 관광"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c0","kind":"concept","title":"우리나라의 식량 자원 — 무엇을 먹고, 어디서 들여올까","text":"식생활의 변화: 예전에는 밥(쌀)이 식사의 중심이었지만, 빵·면 같은 밀가루 음식과 고기를 먹는 일이 늘면서 한 사람이 먹는 쌀의 양은 크게 줄었어요. 대신 밀과 고기 소비가 늘었어요. 식량 자원의 수입 쌀은 대부분 국내에서 생산해요. 밀·옥수수·콩은 국내 생산이 매우 적어 대부분 수입","keywords":["식량 자급률"],"ref":{"tab":"concepts","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c1","kind":"concept","title":"우리나라의 에너지 자원 — 대부분을 수입해요","text":"우리나라는 공장·자동차·가정에서 에너지를 많이 쓰지만, 석유·천연가스 같은 에너지 자원이 거의 나지 않아요. 그래서 쓰는 에너지의 90% 넘게를 수입해요. 에너지 자원 · 쓰임 · 주로 들여오는 곳 석유(원유) · 자동차 연료, 석유 화학 제품의 원료 · 사우디아라비아 등 서남아시아 천","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c2","kind":"concept","title":"자원 문제와 지속가능한 자원 확보","text":"자원의 특성 유한성: 석유·석탄 같은 자원은 쓰면 쓸수록 줄어들고, 언젠가 바닥날 수 있어요. 편재성: 자원은 지구에 고르게 있지 않고, 석유가 서남아시아에 많이 묻혀 있는 것처럼 특정 지역에 치우쳐 있어요. 자원 문제 인구가 늘고 산업이 발달하면서 자원을 쓰는 양이 계속 늘어요. 자원","keywords":["자원 민족주의","신·재생 에너지"],"ref":{"tab":"concepts","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c3","kind":"concept","title":"지역 개발과 환경 보존 — 글로컬 환경 이슈","text":"글로컬은 세계를 뜻하는 글로벌(global)과 지역을 뜻하는 로컬(local)을 합친 말이에요. \"생각은 세계적으로, 행동은 지역에서\"라는 뜻을 담고 있어요. 한 지역의 개발 문제가 그 지역에만 머물지 않고 세계의 환경 문제와 이어지는 것을 글로컬 환경 이슈라고 할 수 있어요. 사례 ·","keywords":["글로컬"],"ref":{"tab":"concepts","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c4","kind":"concept","title":"더 나은 지역을 만드는 사람들의 노력","text":"세계 곳곳에서 사람들은 환경을 지키면서도 살기 좋은 지역을 만들기 위해 노력하고 있어요. 국내 사례 순천만(전라남도): 갈대밭과 갯벌 주변의 전봇대를 없애고 논을 철새 쉼터로 가꾸었어요. 그러자 철새가 더 많이 찾아오고, 생태 관광객이 늘어 지역 경제에도 도움이 되었어요. 태화강(울산)","keywords":["생태 관광"],"ref":{"tab":"concepts","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#c5","kind":"concept","title":"우리 지역 문제의 해결 방안을 찾아 실천하기","text":"우리 지역의 문제도 우리가 직접 해결에 나설 수 있어요. 다음 순서로 해 볼 수 있어요. 문제 찾기: 우리 동네에서 불편하거나 걱정되는 점을 찾아요(예: 통학로가 위험해요, 하천에 쓰레기가 많아요). 자료 조사: 현장을 직접 둘러보고(답사), 주민에게 설문하고, 지도와 통계를 찾아봐요.","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t0","kind":"term","title":"식량 자급률","text":"나라 안에서 필요한 식량 가운데 국내에서 생산하는 식량의 비율이에요. 우리나라는 곡물 자급률이 낮은 편이에요.","keywords":["식량 자급률"],"ref":{"tab":"terms","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t1","kind":"term","title":"식량 안보","text":"모든 사람이 언제나 충분한 식량을 안정적으로 얻을 수 있는 상태예요.","keywords":["식량 안보"],"ref":{"tab":"terms","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t2","kind":"term","title":"푸드 마일리지","text":"식품의 무게(t)에 이동 거리(km)를 곱한 값이에요. 클수록 운송에 에너지가 많이 들고 온실가스가 많이 나와요.","keywords":["푸드 마일리지"],"ref":{"tab":"terms","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t3","kind":"term","title":"로컬 푸드","text":"가까운 지역에서 생산해 그 지역에서 소비하는 먹을거리예요.","keywords":["로컬 푸드"],"ref":{"tab":"terms","idx":3},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t4","kind":"term","title":"자원의 편재성","text":"자원이 지구에 고르게 있지 않고 특정 지역에 치우쳐 분포하는 특성이에요.","keywords":["자원의 편재성"],"ref":{"tab":"terms","idx":4},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t5","kind":"term","title":"자원 민족주의","text":"자원을 가진 나라가 자원을 자기 나라의 이익을 위한 무기처럼 쓰는 움직임이에요.","keywords":["자원 민족주의"],"ref":{"tab":"terms","idx":5},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t6","kind":"term","title":"신·재생 에너지","text":"햇빛·바람·물·땅속의 열처럼 다시 쓸 수 있는 에너지와 수소 같은 새로운 에너지예요. 온실가스를 적게 내보내요.","keywords":["신·재생 에너지"],"ref":{"tab":"terms","idx":6},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t7","kind":"term","title":"지속가능한 발전","text":"미래 세대가 쓸 몫을 해치지 않으면서 지금 세대의 필요를 채우는 발전이에요.","keywords":["지속가능한 발전"],"ref":{"tab":"terms","idx":7},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t8","kind":"term","title":"글로컬","text":"글로벌(세계)과 로컬(지역)을 합친 말로, 세계적인 시각으로 생각하고 지역에서 실천한다는 뜻이에요.","keywords":["글로컬"],"ref":{"tab":"terms","idx":8},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#t9","kind":"term","title":"생태 관광","text":"자연을 해치지 않으면서 자연과 지역 문화를 체험하고 배우는 관광이에요.","keywords":["생태 관광"],"ref":{"tab":"terms","idx":9},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#f0","kind":"faq","title":"우리나라는 쌀이 남는다는데 왜 식량 자급률이 낮아요?","text":"쌀은 대부분 국내에서 생산하지만, 밀·옥수수·콩은 대부분 수입하기 때문이에요. 특히 옥수수와 콩은 가축의 사료로 많이 쓰여서, 고기를 많이 먹을수록 수입하는 곡물이 늘어나요. 그래서 쌀만 보면 넉넉해 보여도 전체 곡물로 보면 자급률이 낮아요.","keywords":["식량 자급률"],"ref":{"tab":"faq","idx":0},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#f1","kind":"faq","title":"신·재생 에너지만 쓰면 안 돼요?","text":"신·재생 에너지는 온실가스를 적게 내보내 좋지만, 햇빛과 바람은 날씨와 시간에 따라 만들어지는 양이 들쭉날쭉해요. 또 발전 시설을 지을 넓은 땅이나 바다가 필요하고, 남는 전기를 저장하는 기술도 더 발전해야 해요. 그래서 신·재생 에너지를 꾸준히 늘리면서 에너지를 아껴 쓰는 노력을 함께 해야 해요.","keywords":["신·재생 에너지"],"ref":{"tab":"faq","idx":1},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#f2","kind":"faq","title":"학생인 제가 지역 문제 해결에 무엇을 할 수 있어요?","text":"할 수 있는 일이 많아요. 동네를 둘러보며 문제를 찾고, 친구들과 설문 조사를 하고, 지방 자치 단체 누리집에 의견을 내거나 캠페인을 열 수 있어요. 일회용품 줄이기, 대중교통 이용하기, 로컬 푸드 고르기처럼 생활 속 작은 실천도 지역과 지구를 바꾸는 힘이 돼요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#m0","kind":"mistake","title":"자주 하는 실수","text":"쌀 자급률과 곡물 자급률을 헷갈리는 실수 — 쌀은 대부분 자급하지만, 밀·옥수수·콩을 대부분 수입해서 전체 곡물 자급률은 낮아요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"},
{"id":"soc-m-2-12#m1","kind":"mistake","title":"자주 하는 실수","text":"편재성과 유한성을 헷갈리는 실수 — 편재성은 \"어디에 있느냐(치우친 분포)\", 유한성은 \"얼마나 있느냐(양이 정해져 있음)\"예요.","keywords":[],"ref":{"tab":"faq"},"subject":"soc","course":"soc-m-2","unit":"soc-m-2-12","grade":"m2"}
]);
